const recipes=[
{id:1,name:"Spicy Chicken Biryani",category:"Pakistani",time:"60 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=900&q=85",description:"Fragrant basmati rice, tender chicken and bold Pakistani spices.",ingredients:["Chicken — 500g","Basmati rice — 500g","Onions — 2","Tomatoes — 2","Yogurt — 1 cup","Biryani masala — 2 tbsp","Ginger garlic paste — 1 tbsp","Oil — 4 tbsp"],steps:["Soak the rice for 20 minutes.","Fry sliced onions until golden.","Add chicken, tomatoes, yogurt and spices; cook until tender.","Parboil the rice separately.","Layer rice over the chicken mixture.","Cover and cook on low heat for 15 minutes.","Gently mix and serve hot with raita."]},
{id:2,name:"Chicken Karahi",category:"Chicken",time:"45 min",difficulty:"Easy",rating:"4.8",image:"/images/chicken_karahi.jpg",description:"A rich, spicy tomato chicken curry made in classic karahi style.",ingredients:["Chicken — 500g","Tomatoes — 4","Green chilies — 4","Ginger — 1 tbsp","Garlic — 1 tbsp","Oil — 4 tbsp","Red chili powder — 1 tsp"],steps:["Heat oil in a karahi.","Add chicken and fry lightly.","Add ginger and garlic.","Add tomatoes and spices.","Cook until the tomatoes break down and chicken is tender.","Finish with green chilies and ginger."]},
{id:3,name:"Classic Cheeseburger",category:"Fast Food",time:"25 min",difficulty:"Easy",rating:"4.7",image:"https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=900&q=85",description:"Juicy homemade burger with melted cheese and fresh vegetables.",ingredients:["Burger buns — 2","Beef patties — 2","Cheese slices — 2","Lettuce","Tomato","Onion","Mayonnaise","Ketchup"],steps:["Cook the beef patties on a hot pan.","Add cheese during the final minute.","Toast the buns.","Spread sauces and add vegetables.","Place the patty inside and serve."]},
{id:4,name:"Chocolate Cake",category:"Dessert",time:"50 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=900&q=85",description:"Soft, rich chocolate cake for birthdays, tea time or dessert cravings.",ingredients:["Flour — 1½ cups","Cocoa powder — ½ cup","Sugar — 1 cup","Eggs — 2","Milk — 1 cup","Butter — 100g","Baking powder — 1 tsp"],steps:["Preheat oven to 180°C.","Mix flour, cocoa and baking powder.","Beat eggs, sugar and butter.","Add milk and dry ingredients.","Pour into a greased pan.","Bake for 35–40 minutes and cool before serving."]},
{id:5,name:"Fresh Green Salad",category:"Healthy",time:"10 min",difficulty:"Easy",rating:"4.6",image:"https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=900&q=85",description:"Crisp vegetables with lemon for a fresh and healthy side.",ingredients:["Cucumber — 1","Tomatoes — 2","Lettuce","Onion — 1","Lemon juice — 1 tbsp","Salt — to taste"],steps:["Wash all vegetables.","Chop cucumber, tomatoes and onion.","Add lettuce.","Season with lemon juice and salt.","Toss and serve fresh."]},
{id:6,name:"Fluffy Pancakes",category:"Breakfast",time:"20 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1528207776546-365bb710ee93?auto=format&fit=crop&w=900&q=85",description:"Soft, fluffy pancakes made for a perfect breakfast.",ingredients:["Flour — 1 cup","Milk — 1 cup","Egg — 1","Sugar — 2 tbsp","Baking powder — 1 tsp","Butter — 2 tbsp"],steps:["Mix flour, sugar and baking powder.","Add milk and egg; whisk until smooth.","Heat a pan with butter.","Pour batter and cook both sides until golden.","Serve with honey or syrup."]},
{id:7,name:"Creamy Garlic Pasta",category:"Fast Food",time:"30 min",difficulty:"Easy",rating:"4.7",image:"https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&w=900&q=85",description:"Creamy garlic pasta with cheese for a quick comfort dinner.",ingredients:["Pasta — 250g","Cream — 1 cup","Cheese — ½ cup","Garlic — 2 cloves","Butter — 1 tbsp","Black pepper"],steps:["Boil pasta until tender.","Melt butter and sauté garlic.","Add cream and black pepper.","Stir in cheese.","Add pasta and toss until coated.","Serve immediately."]},
{id:8,name:"Chicken Tikka",category:"Chicken",time:"40 min",difficulty:"Medium",rating:"4.8",image:"https://images.unsplash.com/photo-1599487488170-d11ec9c172f0?auto=format&fit=crop&w=900&q=85",description:"Smoky, spicy grilled chicken with a delicious charred finish.",ingredients:["Chicken pieces — 500g","Yogurt — ½ cup","Tikka masala — 2 tbsp","Lemon juice — 2 tbsp","Ginger garlic paste — 1 tbsp","Oil — 2 tbsp"],steps:["Mix yogurt, tikka masala, lemon and ginger garlic.","Marinate chicken for at least 30 minutes.","Thread onto skewers.","Grill until cooked and lightly charred.","Brush with butter or oil and serve hot."]},
{id:9,name:"Lahori Chana Chaat",category:"Pakistani",time:"15 min",difficulty:"Easy",rating:"4.8",image:"/images/chana_chaat.jpg",description:"Tangy, spicy chickpea street-food salad with potatoes, tamarind and onion.",ingredients:["Boiled chickpeas — 2 cups","Boiled potatoes — 2 diced","Onion — 1 finely chopped","Tomato — 1 chopped","Green chili — 2","Tamarind chutney — 3 tbsp","Chaat masala — 1 tsp"],steps:["Combine boiled chickpeas and diced potatoes in a mixing bowl.","Add chopped onions, tomatoes, and fresh green chilies.","Drizzle tangy tamarind chutney and sprinkle chaat masala.","Toss everything together and garnish with fresh coriander."]},
{id:10,name:"Crispy Fried Chicken",category:"Fast Food",time:"35 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1562967914-608f82629710?auto=format&fit=crop&w=900&q=85",description:"Golden extra-crispy fried chicken wings and drumsticks seasoned to perfection.",ingredients:["Chicken pieces — 600g","All-purpose flour — 1½ cups","Cornstarch — 2 tbsp","Buttermilk — 1 cup","Garlic powder — 1 tsp","Paprika — 1 tsp","Oil for deep frying"],steps:["Marinate chicken in spiced buttermilk for 1 hour.","Mix flour, cornstarch, paprika, garlic powder, salt, and pepper in a shallow bowl.","Dredge chicken pieces thoroughly in the flour mix.","Heat oil to 175°C (350°F) and fry chicken until deeply golden and cooked through (12–14 min).","Drain on a wire rack and serve piping hot."]},
{id:11,name:"Gulab Jamun (Rose & Cardamom Syrup)",category:"Dessert",time:"35 min",difficulty:"Medium",rating:"5.0",image:"/images/gulab_jamun.jpg",description:"Soft, melt-in-the-mouth golden fried milk dumplings soaked in a warm, fragrant rosewater, saffron, and cardamom sugar syrup.",ingredients:["Full-cream milk powder — 1 cup","All-purpose flour (maida) — 2 tbsp","Baking powder — ¼ tsp","Desi Ghee — 1 tbsp + Ghee for deep frying","Warm whole milk — 4-5 tbsp","Sugar — 1½ cups","Water — 1½ cups","Cardamom pods — 4 cracked","Rose water — 1 tsp","Slivered pistachios & almonds — for garnish"],steps:["Prepare syrup: Simmer sugar, water, cracked cardamom pods, and saffron strands for 6-8 minutes until sticky. Stir in rose water and keep warm.","In a bowl, mix milk powder, flour, and baking powder. Rub in 1 tbsp ghee, then gradually add milk to form a soft, pliable dough.","Cover and rest dough for 5 minutes, then shape into small, completely smooth crack-free balls.","Heat ghee in a deep kadai over low-medium heat. Fry balls gently, continuously swirling the oil so they fry uniformly into a deep golden-brown color (8-10 minutes).","Immediately drain and drop hot gulab jamuns into the warm sugar syrup.","Let them soak for at least 45 minutes to 1 hour to absorb the sweet syrup completely. Garnish with slivered pistachios."]},
{id:12,name:"Avocado Toast with Poached Egg",category:"Breakfast",time:"12 min",difficulty:"Easy",rating:"4.7",image:"https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=900&q=85",description:"Artisan sourdough toast topped with mashed seasoned avocado and a runny poached egg.",ingredients:["Sourdough bread — 2 slices","Ripe avocado — 1","Eggs — 2","Lemon juice — 1 tsp","Red chili flakes — ½ tsp","Sea salt & black pepper — to taste","Olive oil — 1 tsp"],steps:["Toast sourdough slices until golden and crisp.","Mash ripe avocado with lemon juice, salt, pepper, and olive oil.","Poach eggs in simmering water for 3 minutes until whites are set and yolks are runny.","Spread mashed avocado generously over warm toast.","Top with poached eggs, chili flakes, and serve immediately."]},
{id:13,name:"Chicken Nihari (Authentic Lahore Style)",category:"Pakistani",time:"50 min",difficulty:"Medium",rating:"5.0",image:"/images/chicken_nihari.jpg",description:"Tender chicken drumsticks and thighs slow-simmered in a rich, velvety aromatic stew infused with whole spices and roasted flour gravy.",ingredients:["Chicken drumsticks & thighs — 800g","Special Nihari masala blend — 3 tbsp","Wheat flour (atta) — 3 tbsp roasted & mixed with water","Desi Ghee or mustard oil — ½ cup","Ginger garlic paste — 2 tbsp","Fried onions (Birista) — ½ cup","Ginger juliennes, sliced green chilies, cilantro & fresh lemon wedges for garnish"],steps:["Heat ghee in a heavy-bottomed pot and sear chicken pieces over medium-high heat until lightly golden.","Add ginger garlic paste and Nihari masala blend; sauté for 3-4 minutes until fragrant oil releases.","Pour in 4 cups of hot water, cover tightly, and simmer on low flame for 35 minutes until chicken is meltingly tender.","Gradually whisk in the roasted wheat flour slurry while stirring continuously to create a smooth, glossy, thick gravy.","Simmer on low heat (Dum) for 10-12 minutes until aromatic red oil (tari) floats to the surface.","Serve hot garnished with julienned fresh ginger, chopped green chilies, coriander, and freshly squeezed lemon juice alongside warm tandoori naan."]},
{id:14,name:"Mediterranean Quinoa Bowl",category:"Healthy",time:"20 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=900&q=85",description:"Nutrient-packed bowl with fluffy quinoa, chickpeas, olives, cherry tomatoes and feta.",ingredients:["Cooked quinoa — 2 cups","Cherry tomatoes — 1 cup halved","Kalamata olives — ½ cup","Cucumber — 1 diced","Feta cheese — ½ cup crumbled","Olive oil — 2 tbsp","Lemon juice — 1 tbsp","Dried oregano — ½ tsp"],steps:["Cook quinoa according to package instructions and let cool slightly.","In a large bowl, arrange quinoa, halved cherry tomatoes, diced cucumber, and olives.","Whisk olive oil, lemon juice, salt, pepper, and oregano for the dressing.","Drizzle dressing over the bowl and top with crumbled feta cheese.","Enjoy fresh for lunch or dinner."]},
{id:15,name:"Strawberry Glazed Donuts",category:"Dessert",time:"40 min",difficulty:"Medium",rating:"4.8",image:"https://images.unsplash.com/photo-1551024506-0bccd828d307?auto=format&fit=crop&w=900&q=85",description:"Soft, airy yeast donuts dipped in vibrant strawberry icing and sprinkles.",ingredients:["Flour — 2 cups","Yeast — 1 tsp","Sugar — 3 tbsp","Warm milk — ¾ cup","Butter — 3 tbsp","Powdered sugar — 1 cup","Strawberry puree — 2 tbsp"],steps:["Prepare dough with flour, yeast, warm milk, sugar, and butter. Let rise for 1 hour.","Roll out dough and cut into donut rings.","Deep fry in warm oil until golden on both sides.","Whisk powdered sugar with strawberry puree to make the glaze.","Dip warm donuts into glaze, add sprinkles, and let set."]},
{id:16,name:"Shakshuka (Eggs in Tomato Sauce)",category:"Breakfast",time:"25 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&w=900&q=85",description:"Poached eggs simmering in a rich spiced sauce of tomatoes, bell peppers, and cumin.",ingredients:["Eggs — 4","Crushed tomatoes — 400g","Bell pepper — 1 chopped","Onion — 1 diced","Garlic — 2 cloves","Cumin & Paprika — 1 tsp each","Fresh parsley & feta"],steps:["Sauté onions, garlic, and bell peppers in olive oil until soft.","Add crushed tomatoes, cumin, paprika, salt, and black pepper. Simmer for 10 minutes.","Use a spoon to create small wells in the sauce and crack an egg into each well.","Cover and cook on low heat for 5-8 minutes until egg whites are set but yolks remain soft.","Garnish with parsley and feta, serve with warm crusty bread."]},
{id:17,name:"Loaded Cheesy Beef Nachos",category:"Fast Food",time:"20 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1513456852971-30c0b8199d4d?auto=format&fit=crop&w=900&q=85",description:"Crispy corn tortilla chips piled high with seasoned beef, melted cheddar, jalapeños, and guacamole.",ingredients:["Tortilla chips — 1 large bag","Ground beef — 300g seasoned with taco spices","Cheddar cheese — 2 cups shredded","Pickled jalapeños — ¼ cup","Pico de gallo salsa — ½ cup","Guacamole — ½ cup","Sour cream — 3 tbsp"],steps:["Preheat oven to 200°C (400°F).","Brown ground beef with taco seasoning in a skillet until fully cooked.","Arrange tortilla chips on a large baking sheet in an even layer.","Top with seasoned beef, black beans, jalapeño slices, and shredded cheddar cheese.","Bake for 8-10 minutes until cheese is bubbly and melted.","Top with fresh salsa, dollops of guacamole, sour cream, and serve immediately."]},
{id:18,name:"Crispy French Fries & Secret Sauce",category:"Fast Food",time:"25 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=900&q=85",description:"Double-fried golden shoestring potatoes seasoned with sea salt and smoked paprika served with tangy dip.",ingredients:["Russet potatoes — 4 large","Vegetable oil — for deep frying","Sea salt — 1 tsp","Smoked paprika — ½ tsp","Garlic powder — ½ tsp","Mayonnaise — 3 tbsp","Ketchup — 2 tbsp","Sweet pickle relish — 1 tbsp"],steps:["Peel and cut potatoes into uniform thin fries (¼ inch).","Soak cut fries in ice-cold water for 30 minutes to remove excess starch, then pat completely dry.","Heat frying oil to 160°C (320°F) and fry potatoes for 4-5 minutes until soft but pale. Remove and drain.","Increase oil temperature to 190°C (375°F) and fry again for 3-4 minutes until deeply golden and extra crispy.","Toss hot fries in a bowl with sea salt, garlic powder, and smoked paprika.","Whisk mayo, ketchup, relish, and pepper to make the signature burger sauce."]},
{id:19,name:"Cheesy Pepperoni Pizza",category:"Fast Food",time:"30 min",difficulty:"Medium",rating:"5.0",image:"https://images.unsplash.com/photo-1628840042765-356cda07504e?auto=format&fit=crop&w=900&q=85",description:"Crispy crust pizza baked with rich herb tomato marinara, melted mozzarella, and spicy beef pepperoni slices.",ingredients:["Pizza dough — 1 ball (300g)","Pizza tomato sauce — ½ cup","Shredded mozzarella — 1½ cups","Pepperoni slices — 20 pieces","Olive oil — 1 tbsp","Dried oregano & basil — 1 tsp","Grated parmesan — 2 tbsp"],steps:["Preheat oven with pizza stone or baking tray to highest setting (240°C / 475°F).","Stretch pizza dough on a lightly floured surface into a 12-inch round circle.","Spread seasoned tomato pizza sauce evenly, leaving a ½ inch crust border.","Sprinkle generous layer of mozzarella cheese and arrange pepperoni slices on top.","Brush crust edges lightly with olive oil and sprinkle dried oregano.","Bake for 10-12 minutes until crust is blistered golden and cheese is bubbling with toasted spots.","Slice into wedges and enjoy hot."]},
{id:20,name:"Crispy Mozzarella Cheese Sticks",category:"Fast Food",time:"20 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1531749668029-2db88e4276c7?auto=format&fit=crop&w=900&q=85",description:"Golden Italian-herb crusted mozzarella sticks with irresistible stretchy cheese pulls and marinara.",ingredients:["Mozzarella string cheese sticks — 8 sticks cut in half","All-purpose flour — ½ cup","Eggs — 2 beaten","Italian breadcrumbs — 1 cup","Garlic powder & oregano — 1 tsp each","Cooking oil for frying","Warm marinara sauce for dipping"],steps:["Unwrap mozzarella sticks and freeze for 20 minutes so they hold shape when frying.","Set up breading station: bowl 1 flour, bowl 2 beaten eggs, bowl 3 breadcrumbs mixed with garlic powder and oregano.","Dredge each cheese stick in flour, dip in egg, then coat thoroughly with breadcrumbs. (Repeat egg & crumb for double crispiness!).","Heat oil in deep pan to 180°C (350°F).","Fry 4-5 sticks at a time for 60-90 seconds until golden brown. Drain quickly.","Serve immediately with warm marinara sauce."]},
{id:21,name:"BBQ Chicken Quesadilla",category:"Fast Food",time:"18 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1618040996337-56904b7850b9?auto=format&fit=crop&w=900&q=85",description:"Crispy toasted flour tortilla filled with smoky BBQ pulled chicken, sweet corn, and melted Monterey Jack.",ingredients:["Flour tortillas — 2 large (10-inch)","Cooked shredded chicken — 1½ cups","Sweet smoky BBQ sauce — 3 tbsp","Cheddar or Monterey Jack cheese — 1½ cups shredded","Sweet corn kernels — ¼ cup","Red onion — 2 tbsp finely diced","Fresh cilantro — chopped","Butter — 1 tbsp"],steps:["Toss shredded chicken with BBQ sauce, diced red onion, and sweet corn in a bowl.","Heat a large flat skillet over medium heat and melt a dab of butter.","Place one flour tortilla in the pan. Sprinkle half the cheese across one side.","Layer the BBQ chicken filling evenly over the cheese, add remaining cheese, and fold tortilla over into a half-moon.","Cook for 3-4 minutes per side pressing gently with a spatula until golden brown and cheese is completely melted.","Cut into 3 wedges and serve with sour cream or salsa."]},
{id:22,name:"Zinger Crunch Chicken Burger",category:"Fast Food",time:"30 min",difficulty:"Medium",rating:"5.0",image:"https://images.unsplash.com/photo-1625813506062-0aeb1d7a094b?auto=format&fit=crop&w=900&q=85",description:"Super crunchy buttermilk battered chicken breast with spicy secret mayo, cheddar, and crisp lettuce on toasted brioche.",ingredients:["Chicken breast fillets — 2","Brioche burger buns — 2","Buttermilk — 1 cup + 1 egg","Flour + cornstarch blend — 1½ cups","Spicy seasoning (paprika, cayenne, garlic, salt) — 2 tbsp","Spicy mayonnaise — 3 tbsp","Pickle chips — 6 slices","Crisp iceberg lettuce"],steps:["Pound chicken breasts to even ½-inch thickness and marinate in spiced buttermilk for 30 minutes.","Whisk flour, cornstarch, cayenne, paprika, garlic powder, and salt. Drizzle 2 tbsp buttermilk into flour to create crunchy flakes.","Dredge chicken into flour mix, dip back into buttermilk, then press firmly into flour mix.","Deep fry at 175°C (350°F) for 6-7 minutes until ultra-crispy, golden, and cooked through (internal 74°C / 165°F).","Toast brioche buns in butter until golden.","Spread spicy mayo on both buns, layer crunchy lettuce, pickles, and the sizzling hot crunchy chicken fillet."]},
{id:23,name:"Loaded Chili Cheese Dogs",category:"Fast Food",time:"20 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1619740455993-9e612b1af08a?auto=format&fit=crop&w=900&q=85",description:"Grilled beef frankfurters nestled in warm bakery buns smothered in hearty chili con carne and warm cheddar cheese sauce.",ingredients:["Jumbo beef hot dogs / franks — 4","Bakery hot dog buns — 4","Hearty beef chili — 1½ cups warmed","Warm cheddar cheese sauce — 1 cup","Red onion — ¼ cup finely diced","Pickled jalapeño slices — 2 tbsp","Yellow mustard — 2 tbsp"],steps:["Preheat a grill pan or cast-iron skillet over medium-high heat.","Lightly score hot dogs with shallow diagonal cuts and grill for 5-6 minutes, turning often until nicely charred and juicy.","Lightly toast the hot dog buns on the grill.","Nestle each hot dog into a warm bun.","Ladle warm beef chili generously over each frank.","Drizzle creamy warm cheddar cheese sauce, drizzle yellow mustard, and garnish with diced red onions and jalapeños."]},
{id:24,name:"Buffalo Hot Chicken Wings & Ranch",category:"Fast Food",time:"35 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1567620832903-9fc6debc209f?auto=format&fit=crop&w=900&q=85",description:"Crispy restaurant-style chicken wings drenched in buttery cayenne pepper sauce served with cool ranch and crisp celery.",ingredients:["Chicken wings & drumettes — 800g","Baking powder — 1 tbsp (for extra crispness)","Garlic powder & salt — 1 tsp each","Cayenne hot sauce (Frank's style) — ½ cup","Melted unsalted butter — 4 tbsp","Honey or brown sugar — 1 tsp","Buttermilk ranch dressing & celery sticks"],steps:["Pat chicken wings completely dry with paper towels. Toss with baking powder, garlic powder, and salt.","Bake on a wire rack at 220°C (425°F) for 40 minutes (or deep fry at 185°C for 10-12 minutes) until blistered and ultra-crispy.","In a saucepan, melt butter and whisk in hot cayenne sauce, honey, and a dash of Worcestershire sauce until smooth.","Transfer piping hot wings to a large metal bowl, pour warm buffalo sauce over them, and toss vigorously to coat every wing.","Serve immediately with cold buttermilk ranch dip and fresh celery sticks."]},
{id:25,name:"Royal Beef Seekh Kabab",category:"Pakistani",time:"35 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=900&q=85",description:"Juicy spiced minced beef skewers charcoal-grilled with aromatic herbs and garam masala.",ingredients:["Minced beef (20% fat) — 600g","Finely chopped onion — 1 (squeezed dry)","Ginger garlic paste — 1½ tbsp","Green chilies — 3 finely minced","Gram flour (roasted besan) — 2 tbsp","Coriander & Cumin powder — 1 tbsp each","Garam masala — 1 tsp","Fresh mint & cilantro — ½ cup chopped"],steps:["Combine minced beef, squeezed onion, ginger garlic, green chilies, herbs, and roasted gram flour in a bowl.","Knead mixture firmly with your hands for 8-10 minutes until sticky and uniform.","Chill in refrigerator for 30 minutes.","Mold seasoned beef around flat metal skewers into cylindrical kababs.","Grill over hot coals or cook in a hot cast iron grill pan with butter for 8-10 minutes, turning regularly.","Smoke with a live charcoal and a drop of ghee for 2 minutes for authentic BBQ aroma.","Serve hot with mint chutney, ring onions, and fresh tandoori naan."]},
{id:26,name:"Degi Mutton Yakhni Pulao",category:"Pakistani",time:"70 min",difficulty:"Hard",rating:"5.0",image:"https://images.unsplash.com/photo-1633945274405-b6c8069047b0?auto=format&fit=crop&w=900&q=85",description:"Fragrant basmati rice slow-cooked in rich whole-spice mutton bone broth with caramelized onions.",ingredients:["Mutton meat on the bone — 750g","Aged long-grain basmati rice — 500g","Onions — 2 large sliced","Yogurt — ½ cup","Fennel seeds & Coriander seeds — 1½ tbsp each (in spice pouch)","Whole spices (cinnamon, cloves, black cardamom, star anise)","Ghee — ½ cup","Ginger garlic paste — 2 tbsp"],steps:["Boil mutton with 6 cups water, spice pouch (fennel, coriander, garlic, onion, whole spices) for 45 minutes to prepare rich Yakhni broth. Strain and keep broth.","In a separate heavy pot, heat ghee and fry sliced onions until deep golden brown. Save half for garnish.","Add ginger garlic paste, cooked mutton pieces, and yogurt. Sauté for 6-8 minutes until fragrant.","Pour the strained mutton broth into the pot and bring to a rolling boil.","Add soaked basmati rice and cook on high heat until 80% of the liquid is absorbed.","Cover with a tight lid on lowest heat (Dum) for 15 minutes.","Fluff gently and serve with cucumber mint raita."]},
{id:27,name:"Lahori Chargha (Whole Fried Chicken)",category:"Pakistani",time:"60 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1587593810167-a84920ea0781?auto=format&fit=crop&w=900&q=85",description:"Steamed then deep-fried whole chicken marinated in tangy Lahori spices and lemon juice.",ingredients:["Whole skinless chicken with deep cuts — 1.2kg","Thick yogurt — ½ cup","Lemon juice — 3 tbsp","Lahori Chargha masala — 3 tbsp","Egg — 1 beaten","Ginger garlic paste — 2 tbsp","Chaat masala for dusting","Oil for deep frying"],steps:["Whisk yogurt, lemon juice, ginger garlic, Chargha masala, egg, and salt into a thick marinade.","Rub marinade deep into chicken cuts and let rest for at least 3 hours or overnight.","Place marinated chicken in a steamer basket and steam over boiling water for 25 minutes until cooked through.","Remove and let cool completely on a wire rack so excess moisture evaporates.","Heat oil in a wok to 180°C and deep fry whole chicken for 6-8 minutes until deeply golden and crispy on all sides.","Dust generously with chaat masala and serve with tamarind sauce and parathas."]},
{id:28,name:"Shahi Haleem (Slow-Cooked Stew)",category:"Pakistani",time:"90 min",difficulty:"Hard",rating:"5.0",image:"/images/shahi_haleem.jpg",description:"Royal slow-simmered hearty stew of shredded beef, broken wheat, barley, and mixed lentils cooked to silky perfection with authentic spices.",ingredients:["Boneless beef shank or mutton — 600g","Broken wheat (dalia) & Pearl barley — 1 cup soaked","Mixed lentils (chana, masoor, moong, mash) — 1 cup soaked","Shahi Haleem spice blend — 3 tbsp","Ginger garlic paste — 2 tbsp","Fried golden onions (Birista) — 1 cup","Desi Ghee — ½ cup","Julienned ginger, chopped mint, green chilies, lemon wedges & chaat masala for topping"],steps:["Soak wheat, barley, and mixed lentils overnight. Pressure-cook with water and turmeric until tender, then coarsely blend or mash.","In a separate pot, heat ghee and sear meat with ginger garlic, whole spices, and Haleem masala blend until oil separates.","Add water and cook meat until meltingly tender. Shred meat finely using two forks or wooden masher.","Combine shredded meat and cooked lentil-wheat mixture in a large heavy pot.","Cook on low heat, pounding continuously with a wooden masher (ghotna) for 30 minutes until silky, thick, and stretchable.","Prepare aromatic tarka: Sauté sliced onions in hot desi ghee until golden brown and pour sizzling over the haleem.","Serve hot topped with fresh ginger strips, chopped mint, lemon wedges, green chilies, and a sprinkle of chaat masala."]},
{id:29,name:"Dhaba Style Dal Tadka",category:"Pakistani",time:"30 min",difficulty:"Easy",rating:"4.9",image:"/images/dal_tadka.jpg",description:"Creamy yellow lentils simmered with aromatics and finished with a sizzling desi ghee tarka of cumin, sliced garlic, and whole red chilies.",ingredients:["Toor dal & Moong dal — 1 cup rinsed","Ripe tomatoes — 2 finely chopped","Onion — 1 finely diced","Desi Ghee — 3 tbsp","Garlic cloves — 6 thinly sliced","Cumin seeds — 1 tsp","Dried whole red chilies — 3","Kashmiri red chili powder & turmeric — 1 tsp each","Hing (asafoetida) — a pinch","Kasoori methi — 1 tsp","Fresh coriander — chopped"],steps:["Pressure-cook toor and moong dal with turmeric, salt, and 3 cups of water for 12 minutes until soft and creamy. Whisk gently.","In a heavy skillet, melt 1 tbsp ghee, sauté diced onions until translucent, add chopped tomatoes, and cook until mashed into a spiced masala.","Pour cooked lentils into the onion-tomato masala and simmer for 5 minutes.","Crush kasoori methi between palms and stir into simmering dal.","Prepare smoky double tadka: In a small pan, heat 2 tbsp desi ghee. Add sliced garlic until golden, add cumin seeds, dried red chilies, hing, and Kashmiri chili powder.","Immediately pour the sizzling fragrant tadka over the dal and cover with lid for 2 minutes to trap the smoke and aroma.","Garnish with fresh coriander and serve piping hot with steamed basmati rice or tandoori roti."]},
{id:30,name:"Murgh Makhani (Butter Chicken)",category:"Chicken",time:"40 min",difficulty:"Medium",rating:"5.0",image:"https://images.unsplash.com/photo-1588166524941-3bf61a9c41db?auto=format&fit=crop&w=900&q=85",description:"Tender tandoori chicken pieces simmered in a velvety, buttery tomato and cashew cream gravy.",ingredients:["Boneless chicken thighs — 600g diced","Fresh tomato puree — 2 cups","Butter — 4 tbsp","Heavy cream — ½ cup","Cashew paste — 2 tbsp","Kasoori methi (dried fenugreek) — 1 tbsp","Honey or sugar — 1 tsp","Garam masala & Kashmiri chili powder — 1 tsp each"],steps:["Marinate chicken in yogurt, lemon juice, chili powder, and ginger garlic for 30 minutes. Pan sear until charred and cooked.","In a saucepan, melt 2 tbsp butter, add whole spices and tomato puree with cashew paste. Simmer for 15 minutes until thick.","Blend tomato sauce until silkily smooth, strain back into pan.","Add cooked chicken pieces, remaining butter, heavy cream, honey, and garam masala.","Simmer on low heat for 7-8 minutes until sauce is glossy.","Crush kasoori methi between your palms and stir into curry. Garnish with a swirl of cream and serve with garlic naan."]},
{id:31,name:"Creamy Chicken Handi",category:"Chicken",time:"35 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1565557623262-b51c2513a641?auto=format&fit=crop&w=900&q=85",description:"Boneless chicken cubes cooked in a traditional claypot gravy with yogurt, cream, and roasted coriander.",ingredients:["Boneless chicken breast / thighs — 500g cubes","Yogurt — ½ cup whisked","Fresh cooking cream — 4 tbsp","Onion paste — 1 cup","Ginger garlic paste — 1½ tbsp","Roasted crushed coriander & cumin — 1 tbsp each","White pepper powder — ½ tsp","Butter / Ghee — 3 tbsp"],steps:["Heat ghee in a handi or heavy pan and fry onion paste until golden.","Add ginger garlic paste and chicken cubes; fry until chicken changes color.","Lower flame, stir in whisked yogurt, white pepper, crushed roasted cumin, and coriander.","Cover and cook on low heat for 12 minutes until chicken is tender.","Pour in cooking cream and simmer for 3 minutes until oil separates.","Garnish with ginger juliennes, green chilies, and serve with hot butter kulchas."]},
{id:32,name:"Chicken Manchurian with Egg Fried Rice",category:"Chicken",time:"30 min",difficulty:"Medium",rating:"4.8",image:"https://images.unsplash.com/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=900&q=85",description:"Crispy chicken bites tossed in sweet, spicy, and tangy Indo-Chinese garlic sauce.",ingredients:["Boneless chicken cubes — 400g","Cornstarch — 3 tbsp + Egg — 1","Garlic — 2 tbsp finely chopped","Ginger — 1 tbsp","Soy sauce & Chili garlic sauce — 2 tbsp each","Tomato ketchup — 3 tbsp","Capsicum & spring onion — ½ cup chopped","Chicken broth — 1 cup"],steps:["Coat chicken with egg, cornstarch, salt, and pepper. Deep fry or pan fry until golden and crispy.","In a wok, heat 2 tbsp oil, stir-fry chopped garlic and ginger for 30 seconds on high heat.","Add capsicum and spring onions, sauté for 1 minute.","Add soy sauce, ketchup, chili garlic sauce, vinegar, and chicken broth. Bring to a boil.","Stir in cornstarch slurry (1 tbsp cornstarch in 2 tbsp water) until sauce thickens to a glossy glaze.","Toss in the crispy chicken bites and coat thoroughly.","Serve hot with wok-tossed egg fried rice."]},
{id:33,name:"Chicken Malai Boti Skewers",category:"Chicken",time:"35 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1603360946369-dc9bb6258143?auto=format&fit=crop&w=900&q=85",description:"Supremely tender and creamy chicken breast chunks marinated in thick cream, green chilies, and white pepper.",ingredients:["Boneless chicken breast — 500g cubes","Heavy cream — 3 tbsp","Thick Greek yogurt — 3 tbsp","Green chili paste — 1 tbsp","Garlic ginger paste — 1 tbsp","White pepper & cumin powder — 1 tsp each","Melted butter for basting"],steps:["Mix heavy cream, yogurt, green chili paste, garlic ginger, white pepper, and salt in a bowl.","Coat chicken cubes thoroughly and marinate for at least 2 hours (or overnight).","Thread chicken onto soaked wooden skewers.","Grill on a hot grill pan or barbecue for 8-10 minutes, turning and basting with melted butter.","Char lightly for a smoky restaurant finish.","Serve with mint raita and soft naan."]},
{id:34,name:"Crispy Chicken Shawarma Wrap",category:"Chicken",time:"25 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1529006557810-274b9b2fc783?auto=format&fit=crop&w=900&q=85",description:"Spiced Middle Eastern shredded chicken wrapped in pita with garlic toum sauce, pickles, and crispy fries.",ingredients:["Boneless chicken thighs — 400g thinly sliced","Shawarma spice blend (cumin, paprika, cinnamon, garlic) — 1½ tbsp","Olive oil & lemon juice — 2 tbsp each","Pita or flatbreads — 3","Garlic Toum sauce or Mayo — 4 tbsp","Pickled cucumbers — sliced","French fries — 1 cup"],steps:["Marinate chicken slices in shawarma spices, olive oil, lemon juice, and garlic for 20 minutes.","Pan-sear on high heat in a cast-iron skillet for 6-8 minutes until nicely charred and juicy.","Warm pita bread on the griddle.","Spread a generous layer of garlic toum sauce across the warm pita.","Fill with sliced shawarma chicken, crunchy pickles, and a handful of hot french fries.","Roll tightly, toast on the pan for 1 minute for a crispy outer crust, and slice diagonally."]},
{id:35,name:"Zafrani Shahi Kheer (Rice Pudding)",category:"Dessert",time:"45 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1517244683847-7456b63c5969?auto=format&fit=crop&w=900&q=85",description:"Rich, slow-simmered basmati rice dessert infused with saffron strands, green cardamom, and toasted pistachios.",ingredients:["Whole full-fat milk — 1.5 liters","Basmati rice — ¼ cup (soaked & crushed)","Sugar — ½ cup (to taste)","Saffron strands — 15 steeped in warm milk","Cardamom powder — ½ tsp","Slivered almonds & pistachios — ¼ cup","Rose water or Kewra water — 1 tsp"],steps:["Soak basmati rice for 30 minutes, then coarsely crush with your fingers.","Bring whole milk to a boil in a heavy-bottomed pot.","Add crushed rice and simmer on low heat for 30-35 minutes, stirring frequently so it doesn't stick.","When rice is creamy and milk has reduced by a third, stir in sugar, cardamom powder, and saffron milk.","Cook for another 8-10 minutes until thick and luscious.","Stir in rose water and half the toasted nuts.","Pour into clay serving bowls, chill in refrigerator for 2 hours, and top with remaining slivered pistachios and edible silver foil."]},
{id:36,name:"Warm Fudgy Chocolate Brownies",category:"Dessert",time:"35 min",difficulty:"Easy",rating:"5.0",image:"https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=900&q=85",description:"Dense, gooey chocolate brownies with glossy crinkly tops, loaded with melted dark chocolate chunks.",ingredients:["Dark chocolate (70%) — 200g","Unsalted butter — ½ cup (115g)","Granulated sugar — ¾ cup","Brown sugar — ½ cup","Eggs — 3 at room temperature","All-purpose flour — ½ cup","Dutch cocoa powder — ¼ cup","Vanilla extract — 1 tsp","Flaky sea salt — for sprinkling"],steps:["Preheat oven to 175°C (350°F) and line an 8-inch square pan with parchment paper.","Melt dark chocolate and butter together in a heatproof bowl over simmering water until smooth. Cool slightly.","In a separate bowl, whisk eggs, granulated sugar, and brown sugar vigorously for 4-5 minutes until pale and frothy (this creates the shiny crinkle top!).","Gently fold in the melted chocolate mixture and vanilla extract.","Sift in flour, cocoa powder, and salt. Fold just until no dry streaks remain.","Pour into prepared pan and bake for 22-25 minutes (center should still be slightly fudgy).","Cool before slicing into squares. Serve with a scoop of vanilla ice cream."]},
{id:37,name:"Mango Cardamom Kulfi",category:"Dessert",time:"20 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1563805042-7684c019e1cb?auto=format&fit=crop&w=900&q=85",description:"Creamy traditional frozen dessert made with ripe Alphonso mango puree, condensed milk, and crushed pistachios.",ingredients:["Sweet mango pulp — 1½ cups","Sweetened condensed milk — 1 can (400g)","Heavy whipping cream — 1 cup","Evaporated milk — 1 cup","Cardamom powder — ½ tsp","Crushed pistachios — 3 tbsp"],steps:["In a blender, combine mango pulp, condensed milk, heavy cream, evaporated milk, and cardamom powder.","Blend on high for 60 seconds until creamy and frothy.","Stir in 2 tbsp of finely crushed pistachios.","Pour mixture into traditional kulfi molds or popsicle containers. Insert wooden sticks.","Freeze for at least 6-8 hours until completely set.","Unmold by running warm water over the outside of the molds for 10 seconds.","Garnish with remaining pistachios and serve frozen."]},
{id:38,name:"Classic New York Cheesecake",category:"Dessert",time:"75 min",difficulty:"Hard",rating:"4.9",image:"https://images.unsplash.com/photo-1533134242443-d4fd215305ad?auto=format&fit=crop&w=900&q=85",description:"Silky smooth, rich baked cheesecake on a buttery graham cracker crust with berry coulis.",ingredients:["Cream cheese (softened) — 600g","Graham cracker / digestive biscuits — 180g crushed","Melted butter — 4 tbsp","Sugar — 1 cup","Sour cream — ½ cup","Eggs — 3","Vanilla extract — 1 tbsp","Lemon zest — 1 tsp"],steps:["Preheat oven to 160°C (325°F). Mix biscuit crumbs with melted butter and press firmly into an 8-inch springform pan. Bake crust for 10 min.","Beat cream cheese and sugar on low speed until smooth and lump-free.","Add sour cream, vanilla, lemon zest, and beat in eggs one at a time on low speed.","Pour batter over crust. Place springform pan in a larger roasting pan with warm water (water bath).","Bake for 55-60 minutes until edges are set but center has a slight jiggle.","Turn off oven, prop door open slightly, and let cool for 1 hour inside oven.","Refrigerate for at least 6 hours before slicing. Serve with fresh raspberry coulis."]},
{id:39,name:"Italian Espresso Tiramisu",category:"Dessert",time:"30 min",difficulty:"Medium",rating:"5.0",image:"https://images.unsplash.com/photo-1571877227200-a0d98ea607e9?auto=format&fit=crop&w=900&q=85",description:"Decadent Italian dessert with espresso-soaked ladyfingers and whipped mascarpone cream dusted with cocoa.",ingredients:["Ladyfinger biscuits (Savoiardi) — 24","Mascarpone cheese — 400g","Heavy whipping cream — 1 cup","Powdered sugar — ½ cup","Freshly brewed strong espresso — 1½ cups cooled","Cocoa powder for dusting","Vanilla extract — 1 tsp"],steps:["Whip heavy cream and powdered sugar to stiff peaks. In another bowl, beat mascarpone cheese with vanilla until smooth.","Gently fold whipped cream into mascarpone mixture.","Quickly dip each ladyfinger into cooled espresso (1-2 seconds) and arrange in a single layer in a serving dish.","Spread half of the mascarpone cream over the biscuit layer.","Add a second layer of dipped ladyfingers and top with remaining mascarpone cream. Smooth with a spatula.","Dust generously with Dutch-process cocoa powder through a fine sieve.","Chill in refrigerator for at least 4 hours before serving."]},
{id:40,name:"Lemon Herb Grilled Salmon & Asparagus",category:"Healthy",time:"20 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?auto=format&fit=crop&w=900&q=85",description:"Pan-seared wild salmon fillets seasoned with garlic, dill, and lemon served alongside crisp tender asparagus.",ingredients:["Fresh salmon fillets — 2 (200g each)","Fresh asparagus spears — 1 bunch trimmed","Olive oil — 2 tbsp","Garlic cloves — 3 minced","Lemon juice & zest — 1 lemon","Fresh dill — 2 tbsp chopped","Sea salt & crushed black pepper"],steps:["Pat salmon fillets dry and season both sides with salt, pepper, garlic, and fresh dill.","Toss trimmed asparagus in 1 tbsp olive oil, salt, and pepper.","Heat a heavy skillet or grill pan over medium-high heat with remaining olive oil.","Place salmon skin-side down and cook undisturbed for 4-5 minutes until skin is crispy.","Flip salmon and add asparagus to the side of the pan. Cook for another 3-4 minutes.","Squeeze fresh lemon juice over salmon and asparagus.","Serve immediately with lemon wedges and a light herb drizzle."]},
{id:41,name:"Avocado & Roasted Chickpea Power Salad",category:"Healthy",time:"15 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=900&q=85",description:"Crispy paprika-roasted chickpeas, creamy avocado, baby spinach, cucumbers, and tahini lemon dressing.",ingredients:["Canned chickpeas — 1 can drained & rinsed","Ripe avocado — 1 sliced","Baby spinach & arugula — 3 cups","English cucumber — 1 diced","Cherry tomatoes — 1 cup halved","Smoked paprika & cumin — 1 tsp each","Tahini — 2 tbsp","Lemon juice — 2 tbsp","Warm water — 1 tbsp to thin dressing"],steps:["Toss drained chickpeas with olive oil, smoked paprika, cumin, and sea salt. Roast in a pan for 8-10 minutes until crunchy.","In a salad bowl, layer baby spinach, arugula, halved tomatoes, diced cucumbers, and sliced avocado.","Whisk tahini, lemon juice, minced garlic, warm water, salt, and pepper into a silky smooth dressing.","Top salad with warm crispy roasted chickpeas and sunflower seeds.","Drizzle creamy tahini dressing over top and enjoy fresh."]},
{id:42,name:"Greek Yogurt Berry Honey Crunch Bowl",category:"Healthy",time:"8 min",difficulty:"Easy",rating:"4.7",image:"https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&w=900&q=85",description:"High-protein thick Greek yogurt layered with organic berries, chia seeds, roasted almonds, and raw honey.",ingredients:["Plain Greek yogurt (0% or 2%) — 1½ cups","Fresh strawberries & blueberries — 1 cup","Toasted granola — ¼ cup","Chia seeds & flax seeds — 1 tbsp each","Sliced roasted almonds — 2 tbsp","Raw organic honey — 1½ tbsp"],steps:["Spoon chilled thick Greek yogurt into a wide breakfast bowl.","Arrange fresh sliced strawberries and blueberries neatly across one side.","Add toasted granola, sliced almonds, and a sprinkle of chia seeds.","Drizzle golden raw honey over the entire bowl.","Serve immediately for an energetic protein-packed meal."]},
{id:43,name:"Sweet Potato & Black Bean Fiesta Bowl",category:"Healthy",time:"25 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=900&q=85",description:"Roasted cinnamon-cumin sweet potato cubes, spiced black beans, sweet corn, brown rice, and cilantro lime dressing.",ingredients:["Sweet potato — 1 large diced","Black beans — 1 cup cooked","Sweet corn kernels — ½ cup","Cooked brown rice — 1½ cups","Fresh cilantro — ¼ cup chopped","Lime juice — 2 tbsp","Olive oil — 1 tbsp","Cumin & chili powder — 1 tsp each"],steps:["Toss sweet potato cubes with olive oil, cumin, chili powder, and salt. Roast at 200°C (400°F) for 20 minutes until tender and caramelized.","Warm black beans with a pinch of garlic powder and cumin.","In a serving bowl, arrange warm brown rice, roasted sweet potatoes, black beans, and sweet corn.","Whisk olive oil, fresh lime juice, salt, and chopped cilantro.","Drizzle dressing over the bowl and garnish with avocado slices and lime."]},
{id:44,name:"Green Goddess Antioxidant Smoothie Bowl",category:"Healthy",time:"10 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1590080875515-8a3a8dc5735e?auto=format&fit=crop&w=900&q=85",description:"Vibrant thick green smoothie bowl with spinach, frozen mango, banana, and coconut milk topped with kiwi and hemp seeds.",ingredients:["Frozen banana — 1","Frozen mango chunks — 1 cup","Baby spinach — 1 large cup packed","Coconut milk or almond milk — ½ cup","Chia seeds — 1 tbsp","Fresh kiwi slices, coconut flakes & hemp seeds for topping"],steps:["Place frozen banana, mango chunks, fresh spinach, and coconut milk into a high-speed blender.","Blend on high, stopping to tamp down ingredients until thick and soft-serve consistency.","Scoop vibrant green smoothie into a chilled bowl.","Neatly arrange kiwi slices, coconut flakes, chia seeds, and berries on top.","Enjoy immediately with a spoon."]},
{id:45,name:"Classic Eggs Benedict with Hollandaise",category:"Breakfast",time:"25 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1608039829572-78524f79c4c7?auto=format&fit=crop&w=900&q=85",description:"Toasted English muffins topped with seared smoked ham, poached eggs, and rich velvety lemon hollandaise sauce.",ingredients:["English muffins — 2 split and toasted","Eggs — 4 (for poaching) + Egg yolks — 2 (for sauce)","Melted butter — ½ cup (warm)","Lemon juice — 1 tbsp","Smoked ham or turkey bacon — 4 slices","White vinegar — 1 tbsp","Fresh chives — chopped"],steps:["Make Hollandaise: Whisk 2 egg yolks and lemon juice in a heatproof bowl over simmering water until pale and thick. Slowly drizzle in warm melted butter while whisking constantly until thick and creamy. Season with salt and cayenne.","Poach eggs in gently simmering water with 1 tbsp vinegar for 3 minutes until whites are firm and yolk is soft.","Pan-sear smoked ham slices until lightly browned.","Place toasted English muffin halves on plates, top each with seared ham and a warm poached egg.","Ladle warm hollandaise sauce generously over eggs and garnish with finely chopped chives."]},
{id:46,name:"Crispy Golden Belgian Waffles",category:"Breakfast",time:"20 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1562376552-0d160a2f238d?auto=format&fit=crop&w=900&q=85",description:"Crispy on the outside, fluffy on the inside Belgian waffles with deep pockets for pure maple syrup and berries.",ingredients:["All-purpose flour — 2 cups","Baking powder — 1 tbsp + Sugar — 2 tbsp","Eggs — 2 separated (whites whipped to stiff peaks)","Milk — 1¾ cups","Melted butter — ½ cup","Vanilla extract — 1 tsp","Pure maple syrup & fresh berries"],steps:["Whisk flour, sugar, baking powder, and salt in a bowl.","In a separate bowl, whisk milk, melted butter, egg yolks, and vanilla. Stir into dry ingredients until combined.","Gently fold whipped egg whites into the batter with a spatula for cloud-like fluffiness.","Preheat and grease waffle iron. Pour batter and cook until golden brown and steam stops (4-5 minutes).","Serve hot topped with fresh strawberries, blueberries, a pat of butter, and maple syrup."]},
{id:47,name:"Lahori Halwa Puri & Chana Platter",category:"Breakfast",time:"40 min",difficulty:"Medium",rating:"5.0",image:"/images/halwa_puri.jpg",description:"The quintessential Lahore breakfast feast: crispy puffed golden puris served with spicy chickpea curry, sweet cardamom semolina halwa, and tangy pickle.",ingredients:["All-purpose flour (maida) — 2 cups","Semolina (sooji) — 1 cup","Sugar — 1 cup","Desi Ghee — ½ cup","Boiled chickpeas — 2 cups with cooking broth","Kalonji (nigella seeds) & cumin — 1 tsp each","Green cardamom pods — 4","Yellow food color or saffron — a pinch","Pickled mango & green chilies — for serving","Oil — for deep frying puris"],steps:["Knead smooth, soft puri dough using flour, salt, oil, and lukewarm water. Rest for 20 minutes.","Prepare Shahi Halwa: Roast semolina in desi ghee over medium heat until aromatic. Slowly add boiling cardamom sugar syrup and stir continuously until thick, glossy, and ghee separates.","Prepare Lahori Chana: Sauté kalonji, cumin seeds, ginger garlic paste, tomatoes, and red chili in ghee. Add boiled chickpeas with their broth, crush a few chickpeas to thicken gravy, and simmer for 15 minutes with fenugreek and black pepper.","Divide puri dough into small balls, grease lightly, roll very thin, and fry in smoking hot oil for 6-8 seconds until magically puffed and golden.","Serve hot puffed puris immediately with the warm sweet halwa, spicy tarkeydar chana, and sour Lahori achar."]},
{id:48,name:"Brioche French Toast with Caramelized Bananas",category:"Breakfast",time:"18 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1484723091739-30a097e8f929?auto=format&fit=crop&w=900&q=85",description:"Thick golden slices of brioche soaked in cinnamon vanilla custard topped with butter-caramelized bananas.",ingredients:["Thick brioche bread — 4 slices","Eggs — 3","Whole milk or cream — ½ cup","Cinnamon & Vanilla extract — 1 tsp each","Butter — 3 tbsp","Bananas — 2 sliced","Brown sugar — 2 tbsp"],steps:["Whisk eggs, milk, cinnamon, vanilla, and a pinch of salt in a shallow dish.","Dip brioche slices into the custard for 15 seconds per side.","Melt 1 tbsp butter in a skillet over medium heat and cook French toast for 3-4 minutes per side until golden brown.","In another pan, melt remaining butter and brown sugar. Add banana slices and cook for 2 minutes until caramelized and syrupy.","Stack warm French toast, spoon caramelized bananas and sauce over top, and dust with powdered sugar."]},
{id:49,name:"Fluffy Garden Herb & Cheese Omelette",category:"Breakfast",time:"10 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1510693206972-df098062cb71?auto=format&fit=crop&w=900&q=85",description:"French-style soft folded eggs filled with creamy goat cheese or cheddar, chives, and cherry tomatoes.",ingredients:["Fresh eggs — 3","Butter — 1½ tbsp","Milk — 1 tbsp","Grated cheddar or goat cheese — ¼ cup","Fresh chives & parsley — 2 tbsp minced","Cherry tomatoes — 4 halved","Salt & freshly cracked black pepper"],steps:["Whisk eggs with milk, salt, and pepper with a fork until completely blended and smooth.","Melt butter in an 8-inch non-stick skillet over medium-low heat.","Pour in eggs and swirl gently, pulling cooked edges toward center so runny egg fills the gaps.","When top is softly set but still creamy, sprinkle cheese, herbs, and tomatoes across one half.","Fold omelette over in half and slide onto a warm plate.","Brush top with a touch of melted butter and sprinkle extra fresh herbs."]},
{id:50,name:"Creamy Tuscan Garlic Chicken",category:"Chicken",time:"30 min",difficulty:"Easy",rating:"5.0",image:"https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=900&q=85",description:"Pan-seared golden chicken breasts in a rich garlic, sun-dried tomato, baby spinach, and parmesan cream sauce.",ingredients:["Boneless skinless chicken breasts — 2 (cut horizontally)","Heavy whipping cream — 1 cup","Sun-dried tomatoes in oil — ½ cup drained & sliced","Fresh baby spinach — 2 cups packed","Garlic cloves — 4 minced","Chicken broth — ½ cup","Grated Parmesan cheese — ½ cup","Olive oil & Butter — 1 tbsp each","Italian seasoning — 1 tsp"],steps:["Season chicken breasts with salt, black pepper, and Italian seasoning.","Heat olive oil and butter in a large skillet over medium-high heat. Sear chicken for 5-6 minutes per side until golden and cooked through. Transfer to a plate.","In the same skillet, sauté minced garlic for 1 minute until fragrant.","Pour in chicken broth and heavy cream; bring to a gentle simmer.","Stir in grated Parmesan and sliced sun-dried tomatoes until the sauce is creamy and smooth.","Add fresh baby spinach and simmer for 2 minutes until wilted.","Return cooked chicken breasts and rested juices back into the skillet, spooning the velvety sauce over top. Serve hot with pasta, rice, or crusty bread."]},
{id:51,name:"Classic Chicken Fettuccine Alfredo",category:"Chicken",time:"25 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1645112411341-6c4fd023714a?auto=format&fit=crop&w=900&q=85",description:"Tender grilled herb chicken breast slices served over fettuccine coated in an authentic Roman-style parmesan butter cream.",ingredients:["Fettuccine pasta — 350g","Boneless chicken breast — 2","Butter — 4 tbsp (½ stick)","Heavy cream — 1¼ cups","Freshly grated Parmigiano-Reggiano — 1 cup","Garlic cloves — 3 minced","Nutmeg — a tiny pinch","Fresh parsley — chopped for garnish"],steps:["Bring a large pot of salted water to a boil and cook fettuccine until al dente (about 9-10 minutes). Reserve ½ cup pasta water before draining.","Season chicken with salt, black pepper, and garlic powder. Pan-sear in olive oil for 6 minutes per side until golden; rest and slice into strips.","In a deep saucepan, melt butter over medium heat. Add minced garlic and cook for 30 seconds.","Pour in heavy cream and bring to a gentle simmer for 3 minutes.","Reduce heat to low and whisk in freshly grated Parmigiano-Reggiano and a pinch of nutmeg until melted and silky smooth.","Toss the drained fettuccine into the sauce, adding a splash of reserved pasta water if needed to reach glossy perfection.","Plate fettuccine, top with sliced chicken breast, extra parmesan, and chopped fresh parsley."]},
{id:52,name:"Crispy Chicken Parmesan (Parmigiana)",category:"Chicken",time:"40 min",difficulty:"Medium",rating:"5.0",image:"https://images.unsplash.com/photo-1632778149955-e80f8ceca2e8?auto=format&fit=crop&w=900&q=85",description:"Crispy herb-panko crusted chicken cutlets smothered in rich marinara, fresh basil, and bubbling melted mozzarella.",ingredients:["Chicken breast cutlets — 2 large (pounded to ½ inch)","Italian seasoned panko breadcrumbs — 1 cup","Grated Parmesan cheese — ½ cup","Eggs — 2 beaten","All-purpose flour — ½ cup","Marinara sauce — 1½ cups","Fresh mozzarella cheese — 150g sliced or shredded","Fresh basil leaves — ¼ cup","Olive oil for shallow frying"],steps:["Preheat oven to 200°C (400°F).","Set up breading station: Flour in bowl 1, beaten eggs in bowl 2, and panko mixed with grated parmesan and Italian herbs in bowl 3.","Dredge chicken cutlets in flour, dip in beaten eggs, and press firmly into panko mixture for full coverage.","Heat ¼ inch of olive oil in a skillet over medium-high heat. Fry cutlets for 3-4 minutes per side until deeply golden and crispy. Drain on paper towels.","Spread ½ cup of marinara sauce in the bottom of a baking dish. Place fried chicken cutlets in the dish.","Top each cutlet with remaining marinara sauce, fresh mozzarella slices, and a sprinkle of parmesan.","Bake for 12-15 minutes until cheese is melted and bubbling with golden brown spots. Garnish with fresh torn basil."]},
{id:53,name:"Japanese Crispy Chicken Katsu Curry",category:"Chicken",time:"45 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?auto=format&fit=crop&w=900&q=85",description:"Crunchy Japanese panko-breaded chicken cutlet sliced over steamed short-grain rice with rich, savory Japanese curry sauce.",ingredients:["Boneless chicken thighs or breasts — 2","Japanese panko breadcrumbs — 1½ cups","Japanese curry roux cubes (e.g., S&B Golden Curry) — 3 cubes","Carrot — 1 chopped","Yellow onion — 1 diced","Potato — 1 peeled & cubed","Chicken stock or water — 3 cups","Steamed Japanese sushi rice — 3 cups","Oil for deep frying"],steps:["In a pot, heat 1 tbsp oil and sauté diced onion, carrot, and potato for 5 minutes.","Add chicken stock, bring to a boil, cover, and simmer for 15 minutes until vegetables are tender.","Turn off heat, break in Japanese curry roux cubes, and stir until completely dissolved. Simmer on low for 5 minutes until thick and glossy.","Pound chicken lightly, season with salt and white pepper, dredge in flour, egg, and coat thoroughly with panko breadcrumbs.","Deep fry chicken in hot oil (175°C / 350°F) for 5-6 minutes until crispy and golden. Drain on a wire rack for 2 minutes, then slice into strips.","Serve steamed short-grain rice on one side of a wide bowl, arrange sliced katsu next to it, and ladle hot curry sauce generously around."]},
{id:54,name:"Sticky Honey Garlic Chicken Thighs",category:"Chicken",time:"25 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&w=900&q=85",description:"Tender, caramelized chicken thighs coated in a sweet, sticky garlic and soy glaze with sesame seeds and green onions.",ingredients:["Boneless skinless chicken thighs — 600g","Honey — ⅓ cup","Low-sodium soy sauce — ¼ cup","Garlic cloves — 6 minced","Apple cider vinegar — 1 tbsp","Cornstarch — 1 tsp dissolved in 1 tbsp water","Toasted sesame oil — 1 tsp","Toasted sesame seeds & sliced scallions for garnish"],steps:["Season chicken thighs lightly with salt and black pepper.","In a bowl, whisk honey, soy sauce, minced garlic, apple cider vinegar, sesame oil, and cornstarch slurry.","Heat 1 tbsp vegetable oil in a heavy skillet or cast iron over medium-high heat.","Add chicken thighs and sear for 5-6 minutes per side until browned and cooked through.","Pour the honey garlic sauce directly into the hot skillet with the chicken.","Simmer for 2-3 minutes, basting chicken continuously as the sauce bubbles into a thick, glossy, sticky glaze.","Garnish with toasted sesame seeds and sliced green onions. Serve over fragrant jasmine rice."]},
{id:55,name:"Smoky Sizzling Chicken Fajitas",category:"Chicken",time:"20 min",difficulty:"Easy",rating:"4.9",image:"/images/chicken_fajitas.jpg",description:"Sizzling cast-iron strips of spiced chicken breast, colorful bell peppers, and caramelized onions served in a smoking skillet with warm tortillas and guacamole.",ingredients:["Chicken breast — 500g sliced into thin strips","Bell peppers (red, green, yellow) — 3 sliced into strips","Red onion — 1 large sliced","Fajita spice blend (chili powder, cumin, smoked paprika, garlic, oregano) — 2 tbsp","Fresh lime juice — 2 tbsp","Olive oil — 2 tbsp","Warm flour tortillas, guacamole, salsa, and sour cream for serving"],steps:["Toss chicken strips with olive oil, lime juice, and fajita seasoning in a bowl. Rest for 15 minutes.","Heat a heavy cast-iron skillet over high heat until smoking hot.","Add 1 tbsp oil and sear chicken strips in a single layer for 5-6 minutes until nicely charred and cooked through. Remove chicken.","Add sliced bell peppers and onions to the smoking skillet; stir-fry for 3-4 minutes until blistered with charred edges yet crisp-tender.","Toss chicken back into the skillet with the sizzling peppers and onions.","Squeeze fresh lime juice over the pan for signature table sizzle and serve immediately with warm tortillas, guacamole, salsa, and sour cream."]},
{id:56,name:"Shahi Mughlai White Chicken Korma",category:"Chicken",time:"40 min",difficulty:"Medium",rating:"5.0",image:"/images/white_chicken_korma.jpg",description:"A royal Mughlai white curry made with tender chicken braised in a luxurious cashew-almond nut cream, whisked yogurt, white pepper, and fragrant kewra water.",ingredients:["Chicken pieces — 750g","Thick yogurt — 1 cup whisked","Blanched almonds & cashews paste — ¼ cup","White onion paste — ½ cup","Ginger garlic paste — 2 tbsp","Whole green cardamom & cloves — 4 each","White pepper powder — 1 tsp","Pure Desi Ghee — 4 tbsp","Kewra water — 1 tsp","Slivered almonds & slit green chilies for garnish"],steps:["Heat ghee in a heavy pot and add green cardamoms, cloves, and bay leaf until aromatic.","Add ginger garlic paste and chicken pieces; sauté on medium heat for 6-8 minutes until chicken turns opaque.","Lower the heat and add whisked yogurt, white onion paste, and white pepper. Stir continuously for 3 minutes to prevent curdling.","Add the cashew and almond nut paste with ½ cup warm water. Mix well.","Cover with a tight lid and simmer on low heat (Dum) for 20 minutes until chicken is tender and fragrant ghee rises to the surface.","Stir in a drop of kewra water and green chili slits.","Garnish with slivered almonds and serve with rogheni naan or sheermal."]},
{id:57,name:"Spicy Peri Peri Flame-Grilled Chicken",category:"Chicken",time:"40 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1598103442097-8b74394b95c6?auto=format&fit=crop&w=900&q=85",description:"Fiery South African-Portuguese style grilled chicken basted in homemade African bird's eye chili, garlic, and citrus sauce.",ingredients:["Chicken leg quarters (with deep slashes) — 4 pieces","Bird's eye red chilies or red jalapeños — 4-5","Garlic cloves — 6","Fresh lemon juice & zest — 1 lemon","Smoked paprika & oregano — 1 tbsp each","Olive oil — ¼ cup","Red wine vinegar — 2 tbsp","Sea salt — 1½ tsp"],steps:["Blend chilies, garlic, lemon juice, zest, smoked paprika, oregano, vinegar, olive oil, and salt in a blender until smooth to create the fiery Peri Peri marinade.","Rub marinade all over chicken leg quarters, getting deep inside the slashes. Marinate in refrigerator for at least 3 hours or overnight.","Preheat barbecue grill or oven grill to medium-high heat (200°C / 400°F).","Place chicken on the grill and cook for 30-35 minutes, turning every 7-8 minutes and basting generously with extra peri-peri sauce.","Cook until skin is beautifully charred and crispy, and chicken juices run clear.","Serve with grilled corn on the cob, spicy peri-peri salted fries, and lemon wedges."]},
{id:58,name:"Crispy Golden Popcorn Chicken Bites",category:"Chicken",time:"20 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1626082927389-6cd097cdc6ec?auto=format&fit=crop&w=900&q=85",description:"Bite-sized tender chicken breast pieces coated in seasoned buttermilk and crispy flour, fried to crunchy golden perfection.",ingredients:["Boneless chicken breast — 500g cut into bite-sized 1-inch cubes","Buttermilk — ¾ cup","All-purpose flour — 1 cup","Cornstarch — ¼ cup","Garlic powder, onion powder & paprika — 1 tsp each","White pepper & salt — 1 tsp each","Oil for deep frying","Honey mustard dip or BBQ sauce"],steps:["Marinate bite-sized chicken cubes in seasoned buttermilk for 20 minutes.","In a wide bowl, whisk flour, cornstarch, garlic powder, onion powder, paprika, salt, and white pepper.","Drizzle 2 tablespoons of buttermilk into the flour mix and rub with your fingers to form small crunchy flakes.","Toss marinated chicken cubes in the seasoned flour mix, pressing firmly so each piece is coated with crunchy bits.","Heat frying oil to 180°C (350°F).","Fry popcorn chicken in small batches for 3-4 minutes until golden brown and extra crunchy. Drain on wire rack.","Dust with a touch of sea salt and serve immediately with honey mustard or garlic dipping sauce."]},
{id:59,name:"Japanese Teriyaki Chicken Rice Bowl (Donburi)",category:"Chicken",time:"25 min",difficulty:"Easy",rating:"4.9",image:"/images/teriyaki_chicken.jpg",description:"Juicy pan-seared chicken thighs glazed in homemade sweet soy teriyaki sauce over steamed rice with steamed broccoli and toasted sesame.",ingredients:["Boneless chicken thighs — 450g","Soy sauce — 3 tbsp","Mirin (Japanese sweet rice wine) — 2 tbsp","Sake or water — 1 tbsp","Brown sugar or honey — 1½ tbsp","Fresh ginger — 1 tsp grated","Garlic clove — 1 minced","Steamed Jasmine or Calrose rice — 2 cups","Steamed broccoli florets & toasted sesame seeds"],steps:["Whisk soy sauce, mirin, sake (or water), brown sugar, and grated ginger in a small bowl until sugar dissolves.","Heat a skillet over medium-high heat. Place chicken thighs smooth-side down and cook for 5 minutes until crispy and golden.","Flip chicken and cook for another 4 minutes until cooked through. Drain excess fat from the pan.","Pour the teriyaki sauce mixture into the pan around the chicken.","Let the sauce bubble and reduce for 2-3 minutes, turning chicken repeatedly until it is thickly coated in a glossy caramel glaze.","Remove chicken to a cutting board and slice into bite-sized strips.","Fill bowls with warm steamed rice, arrange sliced teriyaki chicken and steamed broccoli, and spoon extra warm teriyaki glaze on top with sesame seeds."]},
{id:60,name:"Moroccan Lemon Olive Chicken Tagine",category:"Chicken",time:"50 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=900&q=85",description:"Aromatic North African chicken braised with preserved lemons, green olives, saffron, ginger, and fresh coriander.",ingredients:["Chicken bone-in pieces (legs & thighs) — 800g","Preserved lemon — 1 (rind finely diced)","Pitted green Moroccan olives — ¾ cup rinsed","Yellow onion — 2 finely grated or chopped","Garlic cloves — 4 minced","Ground ginger & cumin — 1 tsp each","Turmeric & Saffron strands — ½ tsp each","Coriander & flat-leaf parsley — ½ cup chopped","Olive oil — 3 tbsp"],steps:["In a tagine or heavy Dutch oven, heat olive oil over medium heat.","Add grated onions, minced garlic, ginger, turmeric, cumin, and steeped saffron. Sauté for 3 minutes until aromatic.","Add chicken pieces and sear on all sides for 8 minutes to absorb the fragrant spices.","Pour in 1 cup of warm water and half the chopped herbs. Bring to a simmer.","Cover tightly with lid, reduce heat to low, and braise gently for 35 minutes until chicken is meltingly tender.","Add diced preserved lemon rind and green olives. Simmer uncovered for 8-10 minutes until the sauce reduces to a thick, glossy consistency.","Garnish with fresh coriander and serve warm with crusty Moroccan bread or fluffy couscous."]},
{id:61,name:"Peshawari Shinwari Lamb Karahi (Namak Mandi)",category:"Pakistani",time:"40 min",difficulty:"Medium",rating:"5.0",image:"https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=900&q=85",description:"Legendary Khyber Pakhtunkhwa Namak Mandi style lamb karahi cooked simply in animal fat or desi ghee with ripe tomatoes, coarse black pepper, and whole green chilies.",ingredients:["Tender lamb or goat cuts (bone-in) — 750g","Ripe red tomatoes — 5 halved","Desi Ghee or lamb tallow (charbi) — ½ cup","Garlic paste (in water) — 2 tbsp","Fresh ginger julienned — 2 tbsp","Whole green chilies (slit) — 6","Coarsely crushed black pepper — 1½ tbsp","Rock salt (namak) — 1 tsp"],steps:["Heat desi ghee or lamb fat in a heavy cast-iron wok (karahi) over high heat until sizzling.","Add lamb pieces and salt; sear on high flame for 6-8 minutes until the meat turns golden-brown on all edges.","Pour in garlic water and ½ cup warm water. Cover with a tight lid and simmer on medium heat for 20-25 minutes until lamb is tender.","Arrange halved tomatoes over the lamb cut-side down. Cover for 5 minutes so steam softens the skins.","Use tongs to easily peel off and discard tomato skins.","Mash the soft tomatoes into the meat using a wooden spatula over high flame, sautéing vigorously (Bhunai) until the tomato juices reduce into a rich, glossy gravy that coats the meat.","Toss in slit green chilies and freshly crushed black pepper during the final 3 minutes of high-heat stir-frying.","Garnish with fresh julienned ginger and serve sizzling hot directly in the karahi with hot tandoori naan and green tea."]},
{id:62,name:"Peshawari Chapli Kabab",category:"Pakistani",time:"30 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1603360946369-dc9bb6258143?auto=format&fit=crop&w=900&q=85",description:"Traditional Khyber Pakhtunkhwa flat patties packed with coarsely crushed pomegranate seeds, coriander, tomatoes, and fried in pure desi ghee.",ingredients:["Minced beef or lamb (with 20% fat) — 500g","Ripe tomatoes — 2 (1 finely chopped, 1 sliced into thin rounds)","Medium onion — 1 finely minced & moisture squeezed out","Green chilies — 3-4 finely chopped","Fresh coriander & mint — ½ cup chopped","Anardana (dried pomegranate seeds) — 1½ tbsp crushed","Coarsely crushed coriander seeds — 1½ tbsp","Roasted cumin powder & garam masala — 1 tsp each","Makki ka atta (fine yellow cornmeal) — 3 tbsp","Egg — 1 beaten","Desi ghee or tallow for shallow frying"],steps:["In a large mixing bowl, combine minced meat, squeezed onions, chopped tomatoes, green chilies, coriander, and mint.","Add crushed anardana, crushed coriander seeds, cumin, garam masala, salt, cornmeal, and beaten egg.","Knead vigorously with your hands for 6-8 minutes until the meat mixture turns sticky and well-bound.","Divide into large balls. Flatten each ball thinly on your palm into a wide disc. Press a round tomato slice firmly into the center.","Heat ghee in a wide flat iron tawa or skillet over medium heat.","Slide the chapli kababs into the hot ghee. Fry for 4-5 minutes per side, gently spooning hot ghee over the tomato side until deeply browned and crispy on the edges.","Serve immediately with naan, onion rings, and sour tamarind chutney."]},
{id:63,name:"Traditional Balochi Sajji with Spiced Rice",category:"Pakistani",time:"60 min",difficulty:"Hard",rating:"5.0",image:"https://images.unsplash.com/photo-1599488615731-7e5c2823ff28?auto=format&fit=crop&w=900&q=85",description:"Authentic Balochistan slow-roasted whole leg of lamb or chicken infused with rock salt, green papaya, and special Sajji masala served over fragrant spiced rice.",ingredients:["Whole chicken or lamb leg (with deep slits) — 1.2kg","Rock salt (namak) — 1½ tbsp","Raw green papaya paste or vinegar — 2 tbsp","Special Sajji masala (coriander, cumin, amchur, carom, black pepper) — 2 tbsp","Fresh lemon juice — 3 tbsp","Desi Ghee or oil — 3 tbsp for basting","Aged basmati rice cooked with whole spices — 3 cups","Lemon wedges and chaat masala for serving"],steps:["Rub the chicken or lamb thoroughly inside and outside with rock salt, raw papaya paste, and lemon juice. Rest for 2 hours.","Thread the meat onto large metal skewers (or place on a roasting rack over a baking pan).","Slow roast over smoky coals or in a preheated oven at 180°C (350°F) for 45-50 minutes, rotating occasionally.","As the meat roasts, baste with melted desi ghee and dust generously with the fragrant Sajji spice blend.","Increase heat to 220°C (425°F) for the last 8 minutes to get an appetizing crisp, golden exterior while remaining juicy inside.","Prepare aromatic basmati rice cooked with whole cardamom, cumin, and fried onions.","Spread the hot spiced rice over a large ceremonial platter (Thaal), rest the sizzling carved Sajji on top, dust with more Sajji masala, and serve with fresh lemon wedges."]},
{id:64,name:"Creamy Garlic Chicken Alfredo Penne",category:"Chicken",time:"25 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1645112411341-6c4fd023714a?auto=format&fit=crop&w=900&q=85",description:"Golden pan-seared garlic chicken breast tossed with al dente penne pasta in a luscious homemade heavy cream and aged Parmigiano-Reggiano sauce.",ingredients:["Boneless chicken breasts — 400g sliced into cutlets","Penne pasta — 300g","Butter — 3 tbsp","Garlic cloves — 5 minced","Heavy whipping cream — 1½ cups","Freshly grated Parmigiano-Reggiano cheese — 1 cup","Italian seasoning & garlic powder — 1 tsp each","Fresh flat-leaf parsley — 2 tbsp chopped","Sea salt & freshly cracked black pepper"],steps:["Boil penne pasta in heavily salted water until al dente. Reserve ½ cup pasta water, then drain.","Season chicken cutlets with salt, pepper, and Italian seasoning.","Melt 1 tbsp butter in a large skillet over medium-high heat. Sear chicken for 4-5 minutes per side until golden brown and cooked through. Remove to a cutting board and slice into strips.","In the same skillet, melt remaining 2 tbsp butter over medium heat. Sauté minced garlic for 1 minute until fragrant.","Pour in heavy whipping cream and bring to a gentle simmer for 3 minutes.","Reduce heat to low and gradually whisk in grated Parmesan cheese until melted and velvety smooth.","Toss the drained penne and sliced chicken into the sauce, adding a splash of reserved pasta water if needed to coat silkily.","Garnish with freshly cracked black pepper and chopped parsley. Serve immediately."]},
{id:65,name:"Korean Sticky Gochujang Fried Chicken (Yangnyeom)",category:"Chicken",time:"35 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1562967914-608f82629710?auto=format&fit=crop&w=900&q=85",description:"Double-fried extra crunchy chicken bites coated in a spicy-sweet fermented Korean gochujang, honey, garlic, and toasted sesame glaze.",ingredients:["Boneless chicken thighs or wings — 650g cut into pieces","Potato starch or cornstarch — ¾ cup","Egg white — 1","Rice wine or mirin — 1 tbsp","Gochujang (Korean chili paste) — 3 tbsp","Honey or corn syrup — 3 tbsp","Brown sugar — 1 tbsp","Soy sauce — 1 tbsp","Minced garlic & ginger — 1 tbsp each","Toasted sesame oil & sesame seeds","Oil for deep frying"],steps:["Season chicken pieces with salt, black pepper, grated ginger, and rice wine. Toss with 1 egg white and coat thoroughly in potato starch.","In a saucepan, combine gochujang, honey, brown sugar, soy sauce, minced garlic, and 2 tbsp water. Simmer on low heat for 3-4 minutes until thick and glossy; stir in sesame oil.","Heat frying oil to 175°C (350°F). Fry chicken in batches for 5-6 minutes. Remove and drain on a wire rack for 5 minutes.","Increase oil temperature to 190°C (375°F). Fry chicken a second time for 2-3 minutes until shatteringly crisp and golden.","Transfer piping hot crispy chicken directly into a large bowl.","Pour the warm sticky gochujang glaze over the chicken and toss quickly until every piece is evenly coated.","Scatter toasted sesame seeds and chopped scallions over top and serve hot."]},
{id:66,name:"Greek Lemon Garlic Roasted Chicken & Potatoes",category:"Chicken",time:"55 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1598514982205-f36b96d1e8d4?auto=format&fit=crop&w=900&q=85",description:"Golden crisp bone-in chicken thighs and Yukon gold potato wedges roasted in a fragrant olive oil, freshly squeezed lemon juice, garlic, and wild mountain oregano bath.",ingredients:["Bone-in chicken thighs — 6 pieces","Yukon gold potatoes — 4 large cut into wedges","Extra virgin olive oil — ⅓ cup","Fresh lemon juice — ⅓ cup (about 2 large lemons)","Garlic cloves — 6 minced","Dried Greek oregano — 1½ tbsp","Chicken stock — ½ cup","Sea salt & cracked black pepper — 1 tsp each","Fresh parsley & lemon slices for serving"],steps:["Preheat oven to 200°C (400°F).","In a glass measuring jug, whisk together olive oil, lemon juice, chicken stock, minced garlic, oregano, salt, and black pepper.","Arrange potato wedges and chicken thighs in a single layer in a large baking dish.","Pour the lemon-garlic marinade evenly over the chicken and potatoes, tossing potatoes lightly to coat.","Roast uncovered for 45-50 minutes, basting chicken and potatoes once halfway through, until chicken skin is blistered and deeply crisp, and potatoes are tender and golden.","Switch broiler on high for 2-3 minutes if extra crispy skin is desired.","Garnish with fresh lemon slices and chopped parsley. Serve with warm pita bread and tzatziki."]},
{id:67,name:"Authentic Philly Cheesesteak Hoagie",category:"Fast Food",time:"20 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=900&q=85",description:"Ultra-thin ribeye steak flash-seared on a smoking flat top with caramelized sweet onions and melted provolone & Cheez Whiz in a toasted Amoroso roll.",ingredients:["Ribeye steak (partially frozen & shaved paper-thin) — 450g","Hoagie or sub rolls — 2 split lengthwise","Yellow sweet onions — 2 thinly sliced","Provolone cheese slices — 4-6","Cheez Whiz or melted cheddar sauce — 3 tbsp","Butter & vegetable oil — 2 tbsp each","Salt & freshly cracked black pepper"],steps:["Heat 1 tbsp oil and 1 tbsp butter on a large griddle or heavy skillet over medium heat. Sauté sliced onions until soft, golden, and caramelized (about 8-10 minutes). Push to the side.","Turn the heat to high. Add remaining oil and place shaved ribeye directly onto the hot surface.","Let it sizzle for 2 minutes, then use two spatulas to quickly chop and tear the meat as it browns.","Season meat generously with salt and coarse black pepper. Mix the caramelized onions back into the beef.","Shape the beef-onion mixture into a long rectangle matching the length of your hoagie roll.","Lay provolone slices over the hot meat. Place the open-faced hoagie roll directly over the melting cheese to steam for 1 minute.","Slide your long spatula underneath the entire stack, flip it into the roll, and drizzle with warm Cheez Whiz. Serve immediately."]},
{id:68,name:"Loaded Supreme Nachos Grande",category:"Fast Food",time:"20 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1513456852971-30c0b8199d4d?auto=format&fit=crop&w=900&q=85",description:"Piled-high stone-ground crispy tortilla chips smothered in molten queso cheese sauce, seasoned ground beef, black beans, pico de gallo, and jalapeño slices.",ingredients:["Stone-ground restaurant style tortilla chips — 1 large bag (350g)","Ground beef or seasoned black beans — 300g","Taco seasoning — 2 tbsp","Molten cheddar queso sauce — 1 cup","Shredded Mexican blend cheese (Monterey Jack & Cheddar) — 2 cups","Pickled jalapeño slices — ¼ cup","Fresh pico de gallo (diced tomatoes, onions, cilantro, lime) — ½ cup","Guacamole & sour cream — ½ cup each"],steps:["In a skillet over medium-high heat, brown the ground beef with taco seasoning and ¼ cup water until cooked and savory.","Preheat oven to 200°C (400°F) or set oven grill to high.","Spread a generous layer of tortilla chips across a wide parchment-lined baking sheet.","Evenly scatter shredded cheese, seasoned ground beef, and black beans over the chips. Add a second layer of chips and cheese on top.","Bake in oven for 6-8 minutes until shredded cheese is bubbling and melted.","Drizzle warm melted queso sauce over the entire hot platter.","Top generously with fresh pico de gallo, pickled jalapeño rings, dollops of cool sour cream, and fresh guacamole. Serve right from the tray."]},
{id:69,name:"Crispy Nashville Hot Chicken Slider",category:"Fast Food",time:"30 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1625813506062-0aeb1d7a094b?auto=format&fit=crop&w=900&q=85",description:"Buttermilk-dunked crispy chicken thigh dipped in fiery cayenne-brown sugar chili oil, nestled on toasted brioche with sweet crinkle-cut pickles and creamy coleslaw.",ingredients:["Boneless skinless chicken thighs — 4 cut in half for sliders","Brioche slider buns — 4 toasted","Buttermilk — 1 cup","All-purpose flour — 1½ cups","Cornstarch — ¼ cup","Cayenne pepper — 2 tbsp","Dark brown sugar — 1½ tbsp","Smoked paprika, garlic powder & chili powder — 1 tsp each","Crispy crinkle-cut dill pickle chips","Creamy cool cabbage slaw — 1 cup","Frying oil"],steps:["Marinate chicken pieces in buttermilk seasoned with hot sauce and salt for 30 minutes.","Whisk flour, cornstarch, salt, and paprika in a shallow bowl. Dredge chicken in flour, dip back into buttermilk, and dredge in flour again.","Heat frying oil to 175°C (350°F). Fry chicken pieces for 6-7 minutes until extra crunchy and golden. Drain on wire rack.","Ladle ½ cup of the piping hot frying oil into a heatproof bowl. Whisk in cayenne pepper, brown sugar, paprika, garlic powder, and a pinch of salt to form the Nashville hot chili oil.","Immediately brush or dunk each crispy chicken piece into the hot chili oil.","Toast brioche slider buns with butter on a skillet.","Assemble sliders: bottom bun, creamy slaw, hot dipped chicken, crinkle pickle chips, and top bun. Enjoy hot!"]},
{id:70,name:"Warm Molten Chocolate Lava Cake",category:"Dessert",time:"25 min",difficulty:"Medium",rating:"5.0",image:"https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=900&q=85",description:"Individual dark chocolate cakes with delicate firm edges that break open into an irresistible warm, flowing molten chocolate center.",ingredients:["Semi-sweet or bittersweet dark chocolate (60-70%) — 120g chopped","Unsalted butter — ½ cup (115g)","Powdered sugar — ½ cup","Eggs — 2 whole + 2 egg yolks","All-purpose flour — 3 tbsp","Pure vanilla extract — 1 tsp","Pinch of fine sea salt","Unsweetened cocoa powder for dusting ramekins","Vanilla bean ice cream & fresh raspberries"],steps:["Preheat oven to 220°C (425°F). Butter four 6-ounce ramekins generously and dust with cocoa powder, tapping out excess.","In a microwave-safe bowl or double boiler, melt chopped dark chocolate and butter together until smooth and glossy.","Whisk in powdered sugar and salt until well incorporated.","Add whole eggs, egg yolks, and vanilla extract; whisk gently until combined and velvety.","Fold in all-purpose flour with a spatula just until no dry pockets remain (do not overmix).","Divide batter equally among prepared ramekins.","Bake for 12-14 minutes until the edges are firm and cake-like, but the center is still soft and slightly jiggly.","Run a small knife around the edges, place an inverted dessert plate on top, and flip quickly. Let sit for 10 seconds, then lift ramekin. Dust with powdered sugar and serve with vanilla ice cream."]},
{id:71,name:"Classic Italian Tiramisu",category:"Dessert",time:"30 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1571877227200-a0d98ea607e9?auto=format&fit=crop&w=900&q=85",description:"Velvety espresso-soaked Savoiardi ladyfingers layered with rich mascarpone zabaglione cream and generously dusted with dark Dutch cocoa powder.",ingredients:["Savoiardi Italian ladyfingers — 24-30 biscuits","Mascarpone cheese (chilled) — 500g","Fresh egg yolks — 4","Granulated sugar — ½ cup","Heavy whipping cream — 1 cup","Strong brewed espresso coffee (cooled) — 1½ cups","Marsala wine or coffee liqueur (optional) — 2 tbsp","Pure vanilla extract — 1 tsp","Dutch unsweetened cocoa powder for dusting"],steps:["In a heatproof bowl set over simmering water (double boiler), whisk egg yolks and sugar for 5 minutes until pale, thick, and sugar dissolves. Remove and cool completely.","In a separate bowl, beat mascarpone cheese and vanilla extract until smooth, then gently fold into the cooled egg mixture.","Whip heavy cream in another bowl until stiff peaks form. Gently fold whipped cream into the mascarpone mixture until light and airy.","Mix cooled espresso and Marsala wine in a wide shallow dish.","Quickly dip each ladyfinger biscuit into the espresso for 1-2 seconds per side (do not oversaturate) and arrange in a single layer at the bottom of an 8x8 inch dish.","Spread half of the mascarpone cream evenly over the soaked biscuits.","Add a second layer of dipped ladyfingers, then cover with the remaining mascarpone cream, smoothing the top.","Cover and refrigerate for at least 6 hours (preferably overnight). Dust generously with dark cocoa powder right before slicing."]},
{id:72,name:"Royal Shahi Saffron Zarda Sweet Rice",category:"Dessert",time:"40 min",difficulty:"Medium",rating:"4.9",image:"https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=900&q=85",description:"Celebratory Mughlai sweet basmati rice infused with fragrant saffron strands, green cardamom, desi ghee, candied fruits, raisins, and roasted nuts.",ingredients:["Aged sella basmati rice — 2 cups (soaked for 2 hours)","Sugar — 1¾ cups","Pure Desi Ghee — ½ cup","Saffron strands — 1 generous pinch steeped in 2 tbsp warm milk","Whole green cardamom pods — 6","Cloves — 4","Kewra water — 1 tsp","Ashrafi / Murabba (candied fruit / tutty fruity) — ½ cup","Almonds, pistachios & cashews (slivered) — ½ cup","Khoya / Mawa (evaporated milk solids) or mini gulab jamun for garnish"],steps:["Boil 6 cups of water in a large pot with green cardamoms, cloves, and saffron milk until fragrant and bright golden-yellow.","Add soaked and drained sella basmati rice. Boil until rice is 85-90% cooked through (firm core). Drain water completely in a colander.","In a heavy-bottomed pot, heat desi ghee on medium flame. Lightly fry slivered almonds, pistachios, cashews, and raisins for 1 minute until fragrant. Remove half for garnish.","In the remaining ghee, add sugar and ½ cup water; simmer for 2-3 minutes until sugar dissolves into a light syrup.","Gently slide the drained warm rice into the sugar syrup, tossing very lightly with a flat wooden spoon to coat without breaking rice grains.","Cook on medium-high heat until most of the syrup bubbles down. Sprinkle kewra water and candied fruits on top.","Cover with a tight lid sealed with a clean kitchen towel (Dum). Place on lowest heat over an iron tawa for 15 minutes.","Gently fluff the golden rice grains, top with crumbled khoya and roasted nuts, and serve warm."]},
{id:73,name:"Mediterranean Quinoa Tabbouleh Superfood Bowl",category:"Healthy",time:"20 min",difficulty:"Easy",rating:"4.8",image:"https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=900&q=85",description:"A crisp superfood bowl packed with fluffy cooked quinoa, mountains of finely chopped Italian parsley, fresh mint, Persian cucumbers, heirloom tomatoes, and extra virgin olive oil.",ingredients:["Tri-color or white quinoa — 1 cup (rinsed & cooked fluffy)","Fresh flat-leaf parsley — 2 large bunches finely chopped","Fresh mint leaves — ½ cup finely chopped","Persian cucumbers — 3 diced small","Ripe heirloom tomatoes — 2 seeded & diced small","Green onions (scallions) — 4 thinly sliced","Extra virgin cold-pressed olive oil — ⅓ cup","Fresh lemon juice — ¼ cup","Ground sumac — 1 tsp","Himalayan pink salt & cracked black pepper"],steps:["Cook rinsed quinoa in 2 cups of water with a pinch of salt for 15 minutes until water is absorbed. Fluff with a fork and cool completely.","Finely chop washed and thoroughly dried parsley and mint leaves.","In a large wooden salad bowl, combine cooled quinoa, chopped parsley, mint, diced cucumbers, tomatoes, and scallions.","In a small mason jar, shake together olive oil, freshly squeezed lemon juice, ground sumac, sea salt, and black pepper until emulsified.","Drizzle the citrus dressing over the salad and toss gently to coat every grain and herb.","Chill for 15 minutes before serving to let flavors marry. Enjoy as a wholesome energizing meal or side."]},
{id:74,name:"Thai Coconut Lentil Sweet Potato Curry",category:"Healthy",time:"30 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=900&q=85",description:"Nutrient-dense red lentils and roasted sweet potato chunks gently simmered in a coconut milk broth with fresh turmeric, baby spinach, and lime juice.",ingredients:["Red split lentils (masoor dal) — 1 cup rinsed","Sweet potatoes — 2 medium peeled & diced into bite-sized cubes","Coconut milk (unsweetened) — 1 can (400ml)","Vegetable stock — 2 cups","Yellow onion — 1 diced","Garlic — 4 cloves minced","Fresh ginger — 1 tbsp grated","Thai red curry paste or yellow curry powder — 2 tbsp","Baby spinach — 3 cups","Fresh lime juice — 2 tbsp","Coconut oil — 1 tbsp"],steps:["Heat coconut oil in a deep pot over medium heat. Sauté diced onion, minced garlic, and grated ginger for 3-4 minutes until softened.","Stir in curry paste and cook for 1 minute until aromatic and fragrant.","Add diced sweet potato cubes and rinsed red lentils, stirring to coat with the curry aromatics.","Pour in vegetable broth and coconut milk. Bring to a boil, then reduce heat to low-medium.","Cover and simmer gently for 20 minutes until sweet potatoes are fork-tender and lentils have melted into a creamy stew.","Stir in fresh baby spinach and cook for 2 minutes until just wilted.","Remove from heat, stir in fresh lime juice and season with salt. Ladle into bowls with brown rice or enjoy as a hearty soup."]},
{id:75,name:"Pan-Seared Citrus Herb Salmon with Asparagus",category:"Healthy",time:"20 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&w=900&q=85",description:"Omega-3 rich wild salmon fillet pan-seared with crispy skin, basted in lemon-dill garlic olive oil alongside tender blistered asparagus spears.",ingredients:["Wild salmon fillets (skin-on) — 2 (approx 180g each)","Fresh asparagus spears (woody ends trimmed) — 1 bunch","Extra virgin olive oil — 2 tbsp","Unsalted butter or ghee — 1 tbsp","Garlic cloves — 3 minced","Fresh dill — 2 tbsp chopped","Fresh lemon juice & zest — 1 lemon","Flaky sea salt & coarse black pepper"],steps:["Pat salmon fillets thoroughly dry with paper towels. Season both sides with flaky sea salt and cracked black pepper.","Heat olive oil in a stainless steel or cast-iron skillet over medium-high heat until shimmering.","Place salmon fillets skin-side down and gently press with a spatula for 10 seconds to ensure even contact. Cook undisturbed for 5 minutes until skin is crispy and golden.","Flip salmon carefully and toss the trimmed asparagus spears directly into the pan alongside the fish.","Add butter, minced garlic, lemon zest, and lemon juice.","Baste the top of the salmon continuously with the bubbling lemon-garlic butter for 2-3 minutes while asparagus blisters and becomes crisp-tender.","Transfer to warm plates, sprinkle with fresh dill, and serve immediately with lemon wedges."]},
{id:76,name:"Nutella & Strawberry Stuffed French Toast",category:"Breakfast",time:"20 min",difficulty:"Easy",rating:"5.0",image:"https://images.unsplash.com/photo-1484723091739-30a097e8f929?auto=format&fit=crop&w=900&q=85",description:"Thick-cut golden brioche slices filled with rich hazelnut Nutella spread and fresh strawberries, soaked in spiced vanilla custard and pan-toasted in butter.",ingredients:["Thick-cut brioche or challah bread — 4 slices","Nutella hazelnut spread — 4 tbsp","Fresh strawberries — 1 cup thinly sliced","Large eggs — 2","Whole milk or half-and-half — ½ cup","Pure vanilla extract — 1 tsp","Ground cinnamon — ½ tsp","Butter for cooking — 2 tbsp","Powdered sugar & pure maple syrup for serving"],steps:["Spread 2 tablespoons of Nutella generously onto two slices of brioche.","Layer thinly sliced fresh strawberries over the Nutella, then top with the remaining brioche slices to form sandwiches. Press edges gently.","In a wide shallow dish, whisk eggs, milk, vanilla extract, cinnamon, and a pinch of salt into a smooth custard.","Melt 1 tbsp butter in a non-stick skillet or griddle over medium heat.","Dip each sandwich into the custard mixture for 10-15 seconds per side, allowing the bread to absorb without getting soggy.","Place sandwiches in the hot pan and cook for 3-4 minutes per side until golden brown and crispy on the outside, and Nutella is melty inside.","Cut diagonally, dust with powdered sugar, and serve with fresh strawberries and warm maple syrup."]},
{id:77,name:"Traditional Cast-Iron Shakshuka with Feta",category:"Breakfast",time:"25 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&w=900&q=85",description:"Farm-fresh organic eggs gently poached in a bubbling cast-iron skillet of spiced tomato, roasted red bell pepper, and cumin sauce topped with crumbled feta.",ingredients:["Large eggs — 4-5","Ripe crushed plum tomatoes (canned or fresh) — 1 can (400g)","Red bell pepper — 1 diced","Yellow onion — 1 diced","Garlic cloves — 3 minced","Ground cumin & smoked paprika — 1 tsp each","Crushed red pepper flakes — ½ tsp","Crumbled Greek feta cheese — ⅓ cup","Fresh cilantro and parsley — 2 tbsp chopped","Olive oil — 2 tbsp","Crusty sourdough bread for dipping"],steps:["Heat olive oil in a heavy cast-iron skillet over medium heat. Sauté diced onion and bell pepper for 5 minutes until soft.","Add minced garlic, cumin, smoked paprika, and chili flakes; sauté for 1 minute until fragrant.","Pour in crushed tomatoes and season with salt and pepper. Simmer gently for 10 minutes until sauce thickens.","Use the back of a large spoon to make 4-5 shallow wells in the bubbling sauce.","Crack an egg carefully into each well.","Reduce heat to medium-low, cover with a lid, and cook for 5-7 minutes until egg whites are just set but yolks remain soft and runny.","Remove from heat, scatter crumbled feta cheese, fresh cilantro, and parsley over the skillet.","Serve immediately straight from the cast iron with warm crusty bread."]},
{id:78,name:"Fluffy Golden Belgian Waffles with Maple Butter",category:"Breakfast",time:"25 min",difficulty:"Easy",rating:"4.9",image:"https://images.unsplash.com/photo-1562376552-0d160a2f238d?auto=format&fit=crop&w=900&q=85",description:"Crisp-on-the-outside and feather-light on the inside Belgian waffles with deep pockets to hold pools of warm maple syrup, whipped cream, and berries.",ingredients:["All-purpose flour — 2 cups","Cornstarch — 2 tbsp (for extra crispness)","Baking powder — 1 tbsp","Sugar — 2 tbsp","Eggs (whites & yolks separated) — 2","Whole milk (lukewarm) — 1¾ cups","Melted unsalted butter — ½ cup (115g)","Pure vanilla extract — 1 tsp","Pinch of salt","Warm maple syrup, whipped cream & mixed berries for serving"],steps:["Preheat your Belgian waffle maker according to manufacturer instructions.","In a large bowl, whisk together flour, cornstarch, baking powder, sugar, and salt.","In a medium bowl, whisk egg yolks, lukewarm milk, melted butter, and vanilla extract.","In a clean glass bowl, whip egg whites with a hand mixer until stiff peaks form.","Pour the milk-yolk mixture into the dry ingredients and stir gently just until combined (small lumps are okay).","Gently fold the whipped egg whites into the batter with a spatula in two batches to keep it light and airy.","Ladle batter into the preheated waffle maker and cook for 4-5 minutes until deep golden brown and crisp.","Serve hot off the iron stacked high with whipped butter, pure warm maple syrup, and fresh berries."]}
];

const grid=document.getElementById("recipeGrid"),search=document.getElementById("searchInput"),modal=document.getElementById("recipeModal"),modalContent=document.getElementById("modalContent"),toast=document.getElementById("toast");

function render(list=recipes, limit=null){
  if (!grid) return;
  grid.innerHTML="";
  
  let targetList = list;
  const maxItems = limit !== null ? limit : (grid.dataset.limit ? parseInt(grid.dataset.limit, 10) : null);
  if (maxItems && maxItems > 0 && targetList.length > maxItems) {
    targetList = targetList.slice(0, maxItems);
  }

  if(!targetList.length){
    grid.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:55px;color:var(--muted)"><h3>No recipes found</h3><p>Try another search or category.</p></div>';
    return;
  }
  targetList.forEach(r=>{
    const card=document.createElement("article");card.className="recipe-card";
    card.innerHTML=`<div class="recipe-photo"><img src="${r.image}" alt="${r.name}" loading="lazy" referrerpolicy="no-referrer"><button class="favorite" aria-label="Favorite">♡</button></div><div class="recipe-body"><h3>${r.name}</h3><p>${r.description}</p><div class="recipe-meta"><span>⏱ ${r.time}</span><span>★ ${r.rating}</span><span>${r.difficulty}</span></div><button class="recipe-button">View recipe</button></div>`;
    card.querySelector(".favorite")?.addEventListener("click",e=>{e.stopPropagation();const b=e.currentTarget;b.classList.toggle("active");b.textContent=b.classList.contains("active")?"♥":"♡";});
    card.querySelector(".recipe-button")?.addEventListener("click",()=>openRecipe(r.id));
    grid.appendChild(card);
  });
}
function filter(q){
  q=(q || "").toLowerCase().trim();
  if (!q) {
    if (grid) render(recipes);
    return;
  }
  const list=recipes.filter(r=>(r.name+" "+r.category+" "+r.description).toLowerCase().includes(q));
  if (grid) render(list, list.length);
  const recEl = document.getElementById("recipes");
  if (recEl) {
    recEl.scrollIntoView({behavior:"smooth"});
  }
}
const sBtn = document.getElementById("searchBtn");
if (sBtn && search) {
  sBtn.onclick=()=>filter(search.value);
}
if (search) {
  search.addEventListener("keydown",e=>{if(e.key==="Enter")filter(search.value)});
}
document.querySelectorAll("[data-search]").forEach(b=>b.onclick=()=>{if(search) search.value=b.dataset.search;filter(b.dataset.search)});
document.querySelectorAll("[data-category]").forEach(b => {
  b.onclick = () => {
    const cat = encodeURIComponent(b.dataset.category);
    window.location.href = `recipes.html?category=${cat}`;
  };
  b.onkeydown = (e) => {
    if (e.key === "Enter") {
      const cat = encodeURIComponent(b.dataset.category);
      window.location.href = `recipes.html?category=${cat}`;
    }
  };
});
const viewAllLink = document.getElementById("viewAllRecipes") || document.getElementById("clearFilter");
if (viewAllLink) {
  viewAllLink.onclick = (e) => {
    // Navigate to recipes page
    window.location.href = "recipes.html";
  };
}

function openRecipe(id){
  const r = recipes.find(x => x.id === id);
  if (!r || !modalContent || !modal) return;

  window.currentRecipeModal = r;
  window.currentServingsMultiplier = 1;

  renderModalRecipeContent(r, 1);
  modal.classList.add("show");
  modal.setAttribute("aria-hidden", "false");
  document.body.style.overflow = "hidden";
}

function renderModalRecipeContent(r, multiplier) {
  const scaledIngredients = r.ingredients.map(ing => {
    if (multiplier === 1) return ing;
    return ing.replace(/^([\d\/\.\s]+)/, (match) => {
      let val = 0;
      if (match.includes('/')) {
        const parts = match.trim().split('/');
        val = parseFloat(parts[0]) / parseFloat(parts[1]);
      } else {
        val = parseFloat(match);
      }
      if (isNaN(val)) return match;
      const scaled = Math.round(val * multiplier * 10) / 10;
      return `${scaled} `;
    });
  });

  modalContent.innerHTML = `
    <div class="modal-hero">
      <img src="${r.image}" alt="${r.name}" referrerpolicy="no-referrer">
    </div>
    <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; margin-top:14px;">
      <div class="eyebrow" style="margin-bottom:0;">${r.category.toUpperCase()} • ★ ${r.rating} • ⏱ ${r.time}</div>
      <span class="badge" style="background:var(--accent-soft); color:var(--accent); font-weight:700; font-size:12px; padding:4px 10px; border-radius:999px;">Chef Tested</span>
    </div>
    <h2 style="font-family:'Playfair Display',serif; font-size:28px; margin-top:8px;">${r.name}</h2>
    <p style="color:var(--muted); margin-top:8px; line-height:1.6;">${r.description}</p>
    
    <div style="display:flex; align-items:center; justify-content:space-between; background:var(--bg-soft); padding:10px 16px; border-radius:12px; margin:16px 0; border:1px solid var(--line); flex-wrap:wrap; gap:10px;">
      <span style="font-size:14px; font-weight:600; color:var(--fg);">Yield / Servings:</span>
      <div style="display:flex; gap:6px;">
        <button type="button" class="btn" style="padding:4px 10px; font-size:12px; border-radius:8px; ${multiplier === 0.5 ? 'background:var(--accent); color:#fff;' : 'background:var(--card); color:var(--fg); border:1px solid var(--line);'}" onclick="changeServings(0.5)">2 servings</button>
        <button type="button" class="btn" style="padding:4px 10px; font-size:12px; border-radius:8px; ${multiplier === 1 ? 'background:var(--accent); color:#fff;' : 'background:var(--card); color:var(--fg); border:1px solid var(--line);'}" onclick="changeServings(1)">4 servings (standard)</button>
        <button type="button" class="btn" style="padding:4px 10px; font-size:12px; border-radius:8px; ${multiplier === 1.5 ? 'background:var(--accent); color:#fff;' : 'background:var(--card); color:var(--fg); border:1px solid var(--line);'}" onclick="changeServings(1.5)">6 servings</button>
        <button type="button" class="btn" style="padding:4px 10px; font-size:12px; border-radius:8px; ${multiplier === 2 ? 'background:var(--accent); color:#fff;' : 'background:var(--card); color:var(--fg); border:1px solid var(--line);'}" onclick="changeServings(2)">8 servings</button>
      </div>
    </div>

    <h3 style="font-family:'Playfair Display',serif; font-size:20px; margin-top:16px; border-bottom:1px solid var(--line); padding-bottom:6px;">Ingredients</h3>
    <ul style="margin-top:10px; padding-left:20px; line-height:1.7; color:var(--fg);">
      ${scaledIngredients.map(x => `<li>${x}</li>`).join("")}
    </ul>

    <h3 style="font-family:'Playfair Display',serif; font-size:20px; margin-top:20px; border-bottom:1px solid var(--line); padding-bottom:6px;">Step-by-Step Instructions</h3>
    <ol style="margin-top:10px; padding-left:20px; line-height:1.7; color:var(--fg);">
      ${r.steps.map(x => `<li>${x}</li>`).join("")}
    </ol>

    <div style="display:flex; gap:10px; flex-wrap:wrap; margin-top:24px; padding-top:16px; border-top:1px solid var(--line);">
      <button class="btn btn-primary" onclick="copyRecipe(${r.id})" style="flex:1; min-width:140px;">📋 Copy Recipe</button>
      <button class="btn" onclick="window.print()" style="flex:1; min-width:140px; background:var(--card); border:1px solid var(--line); color:var(--fg);">🖨️ Print Recipe</button>
      <button class="btn" onclick="shareRecipe(${r.id})" style="flex:1; min-width:140px; background:var(--card); border:1px solid var(--line); color:var(--fg);">🔗 Share Recipe</button>
    </div>
  `;
}

function changeServings(multiplier) {
  if (!window.currentRecipeModal) return;
  window.currentServingsMultiplier = multiplier;
  renderModalRecipeContent(window.currentRecipeModal, multiplier);
}

function shareRecipe(id) {
  const r = recipes.find(x => x.id === id);
  if (!r) return;
  const shareUrl = `${window.location.origin}/recipes.html?search=${encodeURIComponent(r.name)}`;
  if (navigator.share) {
    navigator.share({
      title: `${r.name} - FlavorNest`,
      text: `Check out this delicious recipe for ${r.name} on FlavorNest!`,
      url: shareUrl
    }).catch(() => {
      navigator.clipboard?.writeText(shareUrl).then(() => showToast("Recipe URL copied to clipboard!"));
    });
  } else {
    navigator.clipboard?.writeText(shareUrl).then(() => showToast("Recipe URL copied to clipboard!"));
  }
}

function closeModal(){
  if (!modal) return;
  modal.classList.remove("show");modal.setAttribute("aria-hidden","true");document.body.style.overflow=""
}
const closeBtn = document.getElementById("closeModal");
if (closeBtn) closeBtn.onclick=closeModal;
if (modal) {
  modal.addEventListener("click",e=>{if(e.target===modal)closeModal()});
}
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal()});
function copyRecipe(id){
  const r=recipes.find(x=>x.id===id);
  if (!r) return;
  const text=`${r.name}\n\nIngredients:\n${r.ingredients.join("\n")}\n\nInstructions:\n${r.steps.map((x,i)=>`${i+1}. ${x}`).join("\n")}\n\nVia FlavorNest Culinary Website`;
  navigator.clipboard?.writeText(text).then(()=>showToast("Recipe copied to clipboard!"));
}
function showToast(msg){
  if (!toast) return;
  toast.textContent=msg;toast.classList.add("show");setTimeout(()=>toast.classList.remove("show"),2200)
}

const sidebarDrawer = document.getElementById("sidebarDrawer");
const sidebarBackdrop = document.getElementById("sidebarBackdrop");
const sidebarToggleBtn = document.getElementById("sidebarToggleBtn");
const sidebarCloseBtn = document.getElementById("sidebarCloseBtn");

function openSidebar() {
  if (sidebarDrawer) sidebarDrawer.classList.add("open");
  if (sidebarBackdrop) sidebarBackdrop.classList.add("show");
  if (sidebarDrawer) sidebarDrawer.setAttribute("aria-hidden", "false");
  document.body.style.overflow = "hidden";
}

function closeSidebar() {
  if (sidebarDrawer) sidebarDrawer.classList.remove("open");
  if (sidebarBackdrop) sidebarBackdrop.classList.remove("show");
  if (sidebarDrawer) sidebarDrawer.setAttribute("aria-hidden", "true");
  document.body.style.overflow = "";
}

if (sidebarToggleBtn) {
  sidebarToggleBtn.onclick = openSidebar;
}
if (sidebarCloseBtn) {
  sidebarCloseBtn.onclick = closeSidebar;
}
if (sidebarBackdrop) {
  sidebarBackdrop.onclick = closeSidebar;
}

document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") {
    closeSidebar();
  }
});

// Sidebar search handler
const sidebarSearchInput = document.getElementById("sidebarSearchInput");
if (sidebarSearchInput) {
  sidebarSearchInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && sidebarSearchInput.value.trim()) {
      const q = encodeURIComponent(sidebarSearchInput.value.trim());
      closeSidebar();
      window.location.href = `recipes.html?search=${q}`;
    }
  });
}

// Sidebar surprise recipe button
const sidebarSurpriseBtn = document.getElementById("sidebarSurpriseBtn");
if (sidebarSurpriseBtn) {
  sidebarSurpriseBtn.onclick = () => {
    closeSidebar();
    const randomRecipe = recipes[Math.floor(Math.random() * recipes.length)];
    if (randomRecipe) {
      if (window.location.pathname.includes("recipes.html") || window.location.pathname.includes("index.html") || window.location.pathname === "/" || window.location.pathname === "") {
        openRecipe(randomRecipe.id);
      } else {
        window.location.href = `recipes.html?category=${encodeURIComponent(randomRecipe.category)}`;
      }
    }
  };
}

// Theme helper that updates both header and sidebar toggles
function updateThemeUI(isDark) {
  const tBtn = document.getElementById("themeBtn");
  const sIcon = document.getElementById("sidebarThemeIcon");
  const sLabel = document.getElementById("sidebarThemeLabel");
  if (tBtn) tBtn.textContent = isDark ? "☀" : "☾";
  if (sIcon) sIcon.textContent = isDark ? "☀" : "☾";
  if (sLabel) sLabel.textContent = isDark ? "Light Mode" : "Dark Mode";
}

const themeBtn = document.getElementById("themeBtn");
const sidebarThemeToggleBtn = document.getElementById("sidebarThemeToggleBtn");

function toggleTheme() {
  document.body.classList.toggle("dark");
  const dark = document.body.classList.contains("dark");
  updateThemeUI(dark);
  localStorage.setItem("flavorDark", dark ? "1" : "0");
}

if (themeBtn) themeBtn.onclick = toggleTheme;
if (sidebarThemeToggleBtn) sidebarThemeToggleBtn.onclick = toggleTheme;

if (localStorage.getItem("flavorDark") === "1") {
  document.body.classList.add("dark");
  updateThemeUI(true);
} else {
  updateThemeUI(false);
}

const menuBtn = document.getElementById("menuBtn");
const navLinks = document.getElementById("navLinks");
if (menuBtn && navLinks) {
  menuBtn.onclick=()=>navLinks.classList.toggle("active");
  document.querySelectorAll(".nav-links a").forEach(a=>a.onclick=()=>navLinks.classList.remove("active"));
}

// Newsletter Subscription with Real Thank-You Email Dispatch
async function handleNewsletterSubmission(e, formEl) {
  if (e) e.preventDefault();
  const emailInput = formEl.querySelector("input[type='email']") || document.getElementById("emailInput");
  if (!emailInput) return;
  const email = (emailInput.value || "").trim();
  if (!email || !email.includes("@")) {
    showToast("Please enter a valid email address.");
    return;
  }

  const submitBtn = formEl.querySelector("button[type='submit']") || formEl.querySelector("button");
  const origBtnText = submitBtn ? submitBtn.textContent : "";
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.textContent = "Sending...";
  }

  let emailResult = {
    success: true,
    email: email,
    message: `Thank you for subscribing! A confirmation email has been dispatched to ${email}.`
  };

  try {
    const res = await fetch("/api/subscribe", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: email })
    });
    if (res.ok) {
      const data = await res.json();
      emailResult = data;
    }
  } catch (err) {
    console.log("Newsletter backend request handled gracefully:", err);
  } finally {
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.textContent = origBtnText;
    }
  }

  emailInput.value = "";
  showToast(`✉️ Thank-you email sent to ${email}!`);
  showThankYouModal(email, emailResult);
}

